ext":""},"staff_invite":{"text":"Hi {name}, you are invited to join {hospital} as {role}. Create your account here: {link} (valid 14 days)","subject":"You are invited to join {hospital}","waTemplate":"","waParams":"name,role,link","smsTemplateId":"","waText":""},"account_created":{"text":"Welcome to {hospital}, {name}! Your {role} account is ready. Sign in at {link} with {email}.","subject":"Welcome to {hospital}","waTemplate":"","waParams":"name,role,link","smsTemplateId":"","waText":"👋 *Welcome to {hospital}*\n\nHi {name}, your *{role}* account is ready.\nSign in: {link}\nE-mail: {email}","pushText":"Your {role} account is ready. Welcome aboard!"},"account_updated":{"text":"Hi {name}, your {hospital} account was updated ({changes}). If this was not you, call {hospital_phone}.","subject":"Your {hospital} account was updated","waTemplate":"","waParams":"name,changes","smsTemplateId":"","waText":"","pushText":"Your account was updated: {changes}"},"account_deleted":{"text":"Hi {name}, your {hospital} sign-in ({email}) has been removed. Your medical records are kept safely. Questions? Call {hospital_phone}.","subject":"Your {hospital} account was removed","waTemplate":"","waParams":"name,email","smsTemplateId":"","waText":""},"password_changed":{"text":"Hi {name}, your {hospital} password was changed on {time}. Not you? Reset it now: {link} or call {hospital_phone}.","subject":"Your password was changed","waTemplate":"","waParams":"name,time,link","smsTemplateId":"","waText":"","pushText":"Your password was changed on {time}. Not you? Reset it right away."},"notice_published":{"text":"{hospital} notice: {title}. {notice} — {link}","subject":"📌 {title}","waTemplate":"","waParams":"title,notice","smsTemplateId":"","waText":"📌 *{title}*\n\n{notice}\n\nRead on the notice board: {link}\n— {hospital}","pushText":"{notice}"}}}}$json$::jsonb)
  on conflict (tenant_id, key) do nothing;
end $$;
revoke all on function public.seed_hospital_defaults(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------------ product page leads (phase 2.2)
-- "Talk to us" form on the Hospital Comrade product page (the platform domain). Platform-level: no tenant_id, only
-- Hospital Comrade admins can read or update them; visitors can only add one through submit_platform_lead().
create table if not exists public.platform_leads (
  id            uuid primary key default gen_random_uuid(),
  created_at    timestamptz not null default now(),
  name          text not null check (char_length(name) between 2 and 100),
  organisation  text not null check (char_length(organisation) between 2 and 150),
  phone         text not null check (phone ~ '^\+?[0-9]{10,13}$'),
  email         text check (email is null or char_length(email) <= 150),
  city          text check (city is null or char_length(city) <= 80),
  plan          text check (plan is null or plan in ('clinic', 'hospital', 'enterprise', 'custom', 'unsure')),
  message       text check (message is null or char_length(message) <= 2000),
  source        text check (source is null or char_length(source) <= 255),
  status        text not null default 'new' check (status in ('new', 'contacted', 'won', 'lost')),
  notes         text
);
create index if not exists platform_leads_created_idx on public.platform_leads (created_at desc);
alter table public.platform_leads enable row level security;
revoke all on public.platform_leads from anon, authenticated;
grant select, update, delete on public.platform_leads to authenticated;
grant all on public.platform_leads to service_role;
drop policy if exists platform_leads_admin on public.platform_leads;
create policy platform_leads_admin on public.platform_leads for all to authenticated
  using (public.provider_role() = 'admin') with check (public.provider_role() = 'admin');

create or replace function public.submit_platform_lead(
  p_name text, p_organisation text, p_phone text, p_email text default null, p_city text default null,
  p_plan text default null, p_message text default null, p_source text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_phone text := regexp_replace(coalesce(p_phone, ''), '[^0-9+]', '', 'g');
        v_email text := nullif(lower(trim(coalesce(p_email, ''))), '');
begin
  if char_length(trim(coalesce(p_name, ''))) < 2 then raise exception 'Please enter your name.'; end if;
  if char_length(trim(coalesce(p_organisation, ''))) < 2 then raise exception 'Please enter your hospital or clinic name.'; end if;
  if v_phone !~ '^\+?[0-9]{10,13}$' then raise exception 'Please enter a valid mobile number.'; end if;
  if v_email is not null and v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email or leave it empty.'; end if;
  -- spam guard: one request per number every 10 minutes, and a ceiling for the whole form
  if exists (select 1 from public.platform_leads where phone = v_phone and created_at > now() - interval '10 minutes') then
    return;   -- already received — quietly accept the repeat
  end if;
  if (select count(*) from public.platform_leads where created_at > now() - interval '1 hour') >= 60 then
    raise exception 'We are receiving a lot of requests right now. Please try again in a few minutes.';
  end if;
  insert into public.platform_leads (name, organisation, phone, email, city, plan, message, source)
  values (left(trim(p_name), 100), left(trim(p_organisation), 150), v_phone, left(v_email, 150), nullif(left(trim(coalesce(p_city, '')), 80), ''),
          case when p_plan in ('clinic', 'hospital', 'enterprise', 'custom', 'unsure') then p_plan end,
          nullif(left(trim(coalesce(p_message, '')), 2000), ''), left(p_source, 255));
end $$;
revoke all on function public.submit_platform_lead(text, text, text, text, text, text, text, text) from public;
grant execute on function public.submit_platform_lead(text, text, text, text, text, text, text, text) to anon, authenticated;

-- ------------------------------------------------------------------ Hospital Comrade messaging (phase 3)
-- Platform-wide settings, no tenant_id. 'messaging' = approved template / DLT IDs for the shared accounts:
--   { "templates": { "<event>": { "waTemplate": "…", "waParams": "name,date", "smsTemplateId": "…" } } }
-- (the shared accounts' credentials are Edge Function secrets — PLATFORM_* — never stored here).
-- Only Hospital Comrade admins read or change it; the notify function reads it with the service role.
create table if not exists public.platform_settings (
  key         text primary key,
  data        jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  updated_by  uuid
);
alter table public.platform_settings enable row level security;
revoke all on public.platform_settings from anon, authenticated;
grant select, insert, update on public.platform_settings to authenticated;
grant all on public.platform_settings to service_role;
drop policy if exists platform_settings_admin on public.platform_settings;
create policy platform_settings_admin on public.platform_settings for all to authenticated
  using (public.provider_role() = 'admin') with check (public.provider_role() = 'admin');
insert into public.platform_settings (key, data) values ('messaging', '{"templates": {}}'::jsonb) on conflict (key) do nothing;

-- record_message_usage(): see billing.sql (it also charges the wallet, phase 4)


-- =====================================================================================================
--  21. LICENCE, WALLET & PAYMENTS — Hospital Comrade phase 4 (loaded last: every hospital table exists)
-- =====================================================================================================
--  • Licence: tenants.trial_ends_at / paid_until → tenant_license() (tenancy_core.sql). In read_only (after the grace
--    period) and suspended hospitals nobody but the platform team can add or change anything: license_guard() runs on
--    every hospital table — also inside website RPCs such as online booking — while reading and signing in still work.
--  • Wallet: prepaid ₹ balance (tenants.wallet_paise) for messages on Hospital Comrade's shared accounts beyond the
--    plan's included messages. Every change is a row in wallet_ledger; usage is one row per day and channel.
--  • Payments: billing_payments (Razorpay orders from the `billing` Edge Function, or manual entries by the platform
--    team). apply_payment() is idempotent: renews the plan or tops up the wallet and numbers the tax invoice.
--  • Prices, GST, trial / grace days and message rates: platform_settings 'billing' (defaults from src/platform/billing.ts);
--    per-hospital overrides in tenants.billing (custom price, included messages, rates).

insert into public.platform_settings (key, data) values ('billing', $json${"currency":"INR","gstPercent":18,"trialDays":14,"graceDays":7,"yearlyMonths":10,"minTopup":500,"maxTopup":100000,"ratesPaise":{"sms":30,"whatsapp":40,"email":2},"plans":{"clinic":{"price":999,"included":{"sms":100,"whatsapp":300,"email":1000}},"hospital":{"price":2999,"included":{"sms":500,"whatsapp":1500,"email":5000}},"enterprise":{"price":7999,"included":{"sms":2000,"whatsapp":5000,"email":20000}},"custom":{"price":null,"included":{"sms":0,"whatsapp":0,"email":0}}},"seller":{"name":"Digital Comrade","gstin":"","address":"","state":"Bihar","email":"","sac":"998315"}}$json$::jsonb)
on conflict (key) do update set data = excluded.data || public.platform_settings.data;   -- new keys arrive, saved values win

create or replace function public.billing_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select data from public.platform_settings where key = 'billing'), '{}'::jsonb)
$$;

-- ------------------------------------------------------------------ tables
create sequence if not exists public.billing_invoice_seq;

create table if not exists public.billing_payments (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at   timestamptz not null default now(),
  kind         text not null check (kind in ('plan', 'wallet')),
  plan         text,
  months       int check (months is null or months between 1 and 36),
  base_paise   bigint not null check (base_paise >= 0),
  gst_paise    bigint not null default 0 check (gst_paise >= 0),
  total_paise  bigint not null check (total_paise >= 0),
  status       text not null default 'created' check (status in ('created', 'paid', 'failed', 'refunded')),
  provider     text not null default 'razorpay' check (provider in ('razorpay', 'manual')),
  order_id     text unique,
  payment_id   text,
  method       text,
  paid_at      timestamptz,
  invoice_no   text unique,
  period_from  date,
  period_to    date,
  buyer        jsonb not null default '{}'::jsonb,       -- legal name / GSTIN / address at the time of payment
  note         text,
  created_by   uuid
);
-- phase 6: the seller printed on the tax invoice, as it was when the invoice was numbered (invoices never change later)
alter table public.billing_payments add column if not exists seller jsonb;
create index if not exists billing_payments_tenant_idx on public.billing_payments (tenant_id, created_at desc);

create table if not exists public.wallet_ledger (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at     timestamptz not null default now(),
  day            date not null default (now() at time zone 'Asia/Kolkata')::date,
  kind           text not null check (kind in ('topup', 'usage', 'refund', 'adjustment')),
  channel        text check (channel is null or channel in ('sms', 'whatsapp', 'email')),
  units          int not null default 0,
  amount_paise   bigint not null,                        -- + credit, − debit
  balance_paise  bigint not null,                        -- balance after this row
  payment        uuid references public.billing_payments (id) on delete set null,
  note           text,
  created_by     uuid
);
create index if not exists wallet_ledger_tenant_idx on public.wallet_ledger (tenant_id, created_at desc);
create unique index if not exists wallet_ledger_usage_day on public.wallet_ledger (tenant_id, day, channel) where kind = 'usage';

-- read: the hospital's owner and accountant (and the platform team working as them); writes only through the functions
do $rls$
declare t text;
begin
  foreach t in array array['billing_payments', 'wallet_ledger'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('drop policy if exists tenant_isolation on public.%I', t);
    execute format('create policy tenant_isolation on public.%I as restrictive for all to anon, authenticated
                      using (tenant_id = (select public.current_tenant())) with check (tenant_id = (select public.current_tenant()))', t);
    execute format('drop policy if exists billing_read on public.%I', t);
    execute format('create policy billing_read on public.%I for select to authenticated using (public.has_role(''owner'', ''accountant''))', t);
    execute format('drop trigger if exists trg_keep_tenant on public.%I', t);
    execute format('create trigger trg_keep_tenant before update of tenant_id on public.%I for each row execute function public.keep_tenant()', t);
  end loop;
end $rls$;

-- the wallet balance and billing overrides are not for visitors or staff (tenants is readable by anon for the website):
-- every other column stays readable, these two only through billing_summary() / my_context()
do $cols$
declare v_cols text;
begin
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols
    from information_schema.columns where table_schema = 'public' and table_name = 'tenants' and column_name not in ('wallet_paise', 'billing', 'close_reason');
  execute 'revoke select on public.tenants from anon, authenticated';
  execute format('grant select (%s) on public.tenants to anon, authenticated', v_cols);
end $cols$;

-- ------------------------------------------------------------------ licence guard
-- Raised for API callers (anon / authenticated — also inside SECURITY DEFINER RPCs, where `role` still names the
-- caller) in read_only / suspended hospitals. The platform team (admin / finance), the service role (Edge Functions)
-- and the database itself are never blocked.
create or replace function public.license_guard()
returns trigger language plpgsql set search_path = public as $$
declare v_tenant uuid; v_state text;
begin
  if coalesce(current_setting('role', true), '') not in ('anon', 'authenticated') then return coalesce(new, old); end if;
  if public.provider_role() in ('admin', 'finance') then return coalesce(new, old); end if;
  -- privacy rights (consent withdrawal, erasure — phase 7) work even when the plan has ended
  if current_setting('app.privacy', true) = 'on' then return coalesce(new, old); end if;
  v_tenant := case when tg_op = 'DELETE' then old.tenant_id else new.tenant_id end;
  v_state := public.tenant_license(v_tenant);
  if v_state in ('read_only', 'suspended') then
    raise exception 'LICENSE_READ_ONLY: This hospital''s Hospital Comrade plan has ended, so the account is read-only. The owner can renew it in Settings → Plan & billing.'
      using errcode = '42501';
  end if;
  return coalesce(new, old);
end $$;

-- every hospital table except the ones that must keep working while read-only (sign-in, password reset, devices,
-- delivery bookkeeping, logs and billing itself)
do $guard$
declare t text;
begin
  for t in select c.table_name from information_schema.columns c
            join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
           where c.table_schema = 'public' and c.column_name = 'tenant_id'
             and c.table_name not in ('tenant_domains', 'provider_assignments', 'provider_audit', 'profiles', 'push_tokens', 'password_reset_otps',
                                      'notification_outbox', 'message_usage', 'audit_log', 'billing_payments', 'wallet_ledger',
                                      'privacy_requests', 'consent_log')  -- phase 7: patients' privacy rights work even when read-only
  loop
    execute format('drop trigger if exists trg_license_guard on public.%I', t);
    execute format('create trigger trg_license_guard before insert or update or delete on public.%I for each row execute function public.license_guard()', t);
  end loop;
end $guard$;

-- ------------------------------------------------------------------ wallet
create or replace function public.wallet_apply(p_tenant uuid, p_kind text, p_amount bigint, p_payment uuid default null,
  p_note text default null, p_channel text default null, p_units int default 0)
returns bigint language plpgsql volatile security definer set search_path = public as $$
declare v_bal bigint; v_day date := (now() at time zone 'Asia/Kolkata')::date;
begin
  update public.tenants set wallet_paise = wallet_paise + p_amount where id = p_tenant returning wallet_paise into v_bal;
  if not found then raise exception 'No hospital with id %', p_tenant; end if;
  if p_kind = 'usage' then   -- one row per day and channel
    insert into public.wallet_ledger (tenant_id, day, kind, channel, units, amount_paise, balance_paise)
    values (p_tenant, v_day, 'usage', p_channel, p_units, p_amount, v_bal)
    on conflict (tenant_id, day, channel) where kind = 'usage' do update
      set units = public.wallet_ledger.units + excluded.units, amount_paise = public.wallet_ledger.amount_paise + excluded.amount_paise,
          balance_paise = excluded.balance_paise, created_at = now();
  else
    insert into public.wallet_ledger (tenant_id, day, kind, channel, units, amount_paise, balance_paise, payment, note, created_by)
    values (p_tenant, v_day, p_kind, p_channel, coalesce(p_units, 0), p_amount, v_bal, p_payment, p_note, auth.uid());
  end if;
  return v_bal;
end $$;

-- the notify function adds each batch's outcome (service role only). Messages on the shared accounts beyond the
-- plan's included messages this month are charged to the wallet (the primary hospital is never charged).
create or replace function public.record_message_usage(p_tenant uuid, p_channel text, p_source text, p_sent int, p_failed int)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  v_month  date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  v_src    text := coalesce(p_source, 'own');
  v_before int;
  v_inc    int;
  v_rate   int;
  v_units  int;
  t        public.tenants;
  cfg      jsonb := public.billing_config();
begin
  if coalesce(p_sent, 0) = 0 and coalesce(p_failed, 0) = 0 then return; end if;
  select sent into v_before from public.message_usage
   where tenant_id = p_tenant and month = v_month and channel = p_channel and source = v_src for update;
  insert into public.message_usage (tenant_id, month, channel, source, sent, failed)
  values (p_tenant, v_month, p_channel, v_src, greatest(coalesce(p_sent, 0), 0), greatest(coalesce(p_failed, 0), 0))
  on conflict (tenant_id, month, channel, source) do update
    set sent = public.message_usage.sent + excluded.sent, failed = public.message_usage.failed + excluded.failed, updated_at = now();
  if v_src <> 'platform' or coalesce(p_sent, 0) <= 0 or p_channel not in ('sms', 'whatsapp', 'email') then return; end if;
  select * into t from public.tenants where id = p_tenant;
  if not found or t.is_primary then return; end if;
  v_inc  := coalesce((t.billing -> 'included' ->> p_channel)::int, (cfg -> 'plans' -> t.plan -> 'included' ->> p_channel)::int, 0);
  v_rate := coalesce((t.billing -> 'ratesPaise' ->> p_channel)::int, (cfg -> 'ratesPaise' ->> p_channel)::int, 0);
  v_before := coalesce(v_before, 0);
  v_units := greatest(0, v_before + p_sent - greatest(v_inc, v_before));
  if v_units > 0 and v_rate > 0 then
    perform public.wallet_apply(p_tenant, 'usage', -(v_units::bigint * v_rate), null, null, p_channel, v_units);
  end if;
end $$;

-- ------------------------------------------------------------------ prices
-- What a plan renewal (1 or 12 months) or a wallet top-up (₹) costs this hospital, GST included.
-- p_plan (phase 6): renew on another plan — it switches when the payment arrives (custom-priced hospitals: ask the team)
drop function if exists public.billing_quote(uuid, text, int, numeric);
create or replace function public.billing_quote(p_tenant uuid, p_kind text, p_months int default 1, p_amount numeric default null, p_plan text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  t      public.tenants;
  v_plan text;
  cfg    jsonb := public.billing_config();
  v_gst  numeric := coalesce((cfg ->> 'gstPercent')::numeric, 18);
  v_price numeric;
  v_base bigint;
  v_from date;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
begin
  select * into t from public.tenants where id = p_tenant;
  if not found then raise exception 'No hospital selected'; end if;
  if p_kind = 'plan' then
    if coalesce(p_months, 0) not in (1, 12) then raise exception 'Choose 1 month or 12 months.'; end if;
    v_plan := coalesce(nullif(p_plan, ''), t.plan);
    if v_plan <> t.plan then
      if not (cfg -> 'plans' ? v_plan) then raise exception 'Unknown plan %', v_plan; end if;
      if (t.billing ->> 'price') is not null then
        raise exception 'Your price was agreed with Hospital Comrade — ask them to change your plan.';
      end if;
    end if;
    v_price := case when v_plan = t.plan then coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric)
                    else (cfg -> 'plans' -> v_plan ->> 'price')::numeric end;
    if v_price is null or v_price <= 0 then
      raise exception 'Your plan is priced individually — Hospital Comrade will send you the payment details.';
    end if;
    v_base := round(v_price * 100 * case when p_months = 12 then coalesce((cfg ->> 'yearlyMonths')::int, 12) else 1 end);
    -- the new period starts after whatever is already paid (or the trial), never in the past
    v_from := greatest(v_today, (greatest(coalesce(t.paid_until, '-infinity'::timestamptz), coalesce(t.trial_ends_at, '-infinity'::timestamptz)) at time zone 'Asia/Kolkata')::date);
    return jsonb_build_object('kind', 'plan', 'plan', v_plan, 'months', p_months, 'base_paise', v_base,
      'gst_paise', round(v_base * v_gst / 100)::bigint, 'total_paise', v_base + round(v_base * v_gst / 100)::bigint, 'gst_percent', v_gst,
      'period_from', v_from, 'period_to', (v_from + make_interval(months => p_months) - interval '1 day')::date);
  elsif p_kind = 'wallet' then
    if p_amount is null or p_amount < coalesce((cfg ->> 'minTopup')::numeric, 500) or p_amount > coalesce((cfg ->> 'maxTopup')::numeric, 100000) then
      raise exception 'Top up between ₹% and ₹%.', coalesce(cfg ->> 'minTopup', '500'), coalesce(cfg ->> 'maxTopup', '100000');
    end if;
    v_base := round(p_amount * 100);
    return jsonb_build_object('kind', 'wallet', 'months', null, 'base_paise', v_base, 'gst_paise', round(v_base * v_gst / 100)::bigint,
      'total_paise', v_base + round(v_base * v_gst / 100)::bigint, 'gst_percent', v_gst);
  end if;
  raise exception 'Unknown payment type';
end $$;

-- ------------------------------------------------------------------ payments
-- Marks a payment paid (once — repeats are ignored), numbers the tax invoice (HC/2026-27/000001, Indian financial
-- year) and applies it: a plan renewal extends paid_until by its months, a top-up credits the wallet (GST excluded).
create or replace function public.apply_payment(p_payment uuid, p_ref text default null, p_method text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  p      public.billing_payments;
  v_d    date := (now() at time zone 'Asia/Kolkata')::date;
  v_fy   text;
  v_inv  text;
  t      public.tenants;
begin
  select * into p from public.billing_payments where id = p_payment for update;
  if not found then raise exception 'Payment not found'; end if;
  if p.status = 'paid' then return jsonb_build_object('ok', true, 'already', true, 'invoice_no', p.invoice_no); end if;
  v_fy := case when extract(month from v_d) >= 4 then to_char(v_d, 'YYYY') || '-' || to_char(v_d + interval '1 year', 'YY')
               else to_char(v_d - interval '1 year', 'YYYY') || '-' || to_char(v_d, 'YY') end;
  v_inv := 'HC/' || v_fy || '/' || lpad(nextval('public.billing_invoice_seq')::text, 6, '0');
  select * into t from public.tenants where id = p.tenant_id for update;
  update public.billing_payments set status = 'paid', paid_at = now(), invoice_no = v_inv,
         payment_id = coalesce(p_ref, payment_id), method = coalesce(p_method, method),
         seller = coalesce(seller, public.billing_config() -> 'seller'),
         buyer = case when buyer = '{}'::jsonb then jsonb_build_object('name', coalesce(t.billing ->> 'legalName', t.name), 'gstin', coalesce(t.billing ->> 'gstin', ''),
                                                                       'address', coalesce(t.billing ->> 'address', '')) else buyer end
   where id = p.id;
  if p.kind = 'plan' then
    update public.tenants
       set plan = coalesce(p.plan, plan),
           paid_until = greatest(now(), coalesce(paid_until, now()), coalesce(trial_ends_at, now())) + make_interval(months => coalesce(p.months, 1)),
           status = case when status = 'suspended' then status else 'active' end
     where id = p.tenant_id;
  else
    perform public.wallet_apply(p.tenant_id, 'topup', p.base_paise, p.id, 'Wallet top-up · ' || v_inv);
  end if;
  return jsonb_build_object('ok', true, 'already', false, 'invoice_no', v_inv);
end $$;

-- ------------------------------------------------------------------ for the app (owner / accountant / platform team)
create or replace function public.billing_summary()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  t      public.tenants;
  cfg    jsonb := public.billing_config();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see billing.' using errcode = '42501'; end if;
  select * into t from public.tenants where id = public.current_tenant();
  if not found then return null; end if;
  return jsonb_build_object(
    'license', public.tenant_license_dates(t.id), 'is_primary', t.is_primary,
    'plan', t.plan,
    'price', coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric),
    'included', coalesce(cfg -> 'plans' -> t.plan -> 'included', '{}'::jsonb) || coalesce(t.billing -> 'included', '{}'::jsonb),
    'rates_paise', coalesce(cfg -> 'ratesPaise', '{}'::jsonb) || coalesce(t.billing -> 'ratesPaise', '{}'::jsonb),
    'wallet_paise', t.wallet_paise,
    'gst_percent', coalesce((cfg ->> 'gstPercent')::numeric, 18), 'yearly_months', coalesce((cfg ->> 'yearlyMonths')::int, 12),
    'min_topup', coalesce((cfg ->> 'minTopup')::numeric, 500), 'max_topup', coalesce((cfg ->> 'maxTopup')::numeric, 100000),
    'buyer', jsonb_build_object('legalName', coalesce(t.billing ->> 'legalName', t.name), 'gstin', coalesce(t.billing ->> 'gstin', ''), 'address', coalesce(t.billing ->> 'address', '')),
    -- phase 6: plan picker + invoices
    'custom_price', (t.billing ->> 'price') is not null,
    'plans', coalesce((select jsonb_object_agg(e.key, jsonb_build_object('price', e.value -> 'price', 'included', e.value -> 'included')) from jsonb_each(cfg -> 'plans') e), '{}'::jsonb),
    'seller', coalesce(cfg -> 'seller', '{}'::jsonb),
    'usage', coalesce((select jsonb_object_agg(channel, sent) from public.message_usage where tenant_id = t.id and month = v_month and source = 'platform'), '{}'::jsonb));
end $$;

drop function if exists public.my_billing_quote(text, int, numeric);
create or replace function public.my_billing_quote(p_kind text, p_months int default 1, p_amount numeric default null, p_plan text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see prices.' using errcode = '42501'; end if;
  return public.billing_quote(public.current_tenant(), p_kind, p_months, p_amount, p_plan);
end $$;

-- phase 6: during the free trial (nothing paid yet) the owner may try another plan straight away
create or replace function public.change_trial_plan(p_plan text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; cfg jsonb := public.billing_config();
begin
  if not public.has_role('owner') then raise exception 'Only the owner can change the plan.' using errcode = '42501'; end if;
  select * into t from public.tenants where id = public.current_tenant() for update;
  if not found or t.is_primary then raise exception 'No plan to change here.'; end if;
  if not (cfg -> 'plans' ? coalesce(p_plan, '')) then raise exception 'Unknown plan %', p_plan; end if;
  if (cfg -> 'plans' -> p_plan ->> 'price') is null then raise exception 'That plan is priced individually — Hospital Comrade will get in touch.'; end if;
  if (t.billing ->> 'price') is not null then raise exception 'Your price was agreed with Hospital Comrade — ask them to change your plan.'; end if;
  if public.tenant_license(t.id) <> 'trial' or coalesce(t.paid_until > now(), false) then
    raise exception 'Your plan is paid — choose the new plan when you renew; it switches when the payment arrives.';
  end if;
  update public.tenants set plan = p_plan, updated_at = now() where id = t.id;
  return public.billing_summary();
end $$;

-- phase 6: messages per month on the shared accounts (sent, included, charged to the wallet) — the usage chart
create or replace function public.billing_usage_history(p_months int default 6)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_t   uuid := public.current_tenant();
  v_now date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  v_n   int := least(greatest(coalesce(p_months, 6), 1), 24);
begin
  if not public.has_role('owner', 'accountant') then raise exception 'Only the owner or accountant can see billing.' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'month', to_char(m.month, 'YYYY-MM'),
      'sent', coalesce((select jsonb_object_agg(u.channel, u.sent) from public.message_usage u where u.tenant_id = v_t and u.month = m.month and u.source = 'platform' and u.channel <> 'push'), '{}'::jsonb),
      'own', coalesce((select sum(u.sent) from public.message_usage u where u.tenant_id = v_t and u.month = m.month and u.source = 'own'), 0),
      'charged_paise', coalesce((select -sum(l.amount_paise) from public.wallet_ledger l where l.tenant_id = v_t and l.kind = 'usage'
                                   and date_trunc('month', l.day)::date = m.month), 0)) order by m.month)
    from (select (v_now - make_interval(months => g))::date as month from generate_series(v_n - 1, 0, -1) g) m), '[]'::jsonb);
end $$;

-- phase 6: renewal reminders to each hospital's owner — 7, 3 and 1 day before the trial / plan ends, and once when the
-- grace period starts. E-mail (+ app push). Daily from the scheduler (Settings → Notifications → automatic delivery).
create or replace function public.queue_billing_reminders()
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  r       record;
  v_count int := 0;
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_left  int;
  v_m     text;
  v_end   timestamptz;
  v_name  text;
  v_mail  text;
  v_prof  uuid;
  v_subj  text;
  v_body  text;
  v_link  text;
  cfg     jsonb := public.billing_config();
begin
  if auth.uid() is not null and coalesce(public.provider_role(), '') <> 'admin' then raise exception 'Not allowed' using errcode = '42501'; end if;
  for r in select t.*, public.tenant_license(t.id) as lic from public.tenants t where not t.is_primary and t.status <> 'suspended' loop
    v_end := greatest(coalesce(r.paid_until, '-infinity'::timestamptz), coalesce(r.trial_ends_at, '-infinity'::timestamptz));
    continue when v_end = '-infinity'::timestamptz;
    v_left := ((v_end at time zone 'Asia/Kolkata')::date - v_today);
    v_m := case when r.lic in ('trial', 'active') and v_left in (7, 3, 1) then 'd' || v_left
                when r.lic = 'grace' then 'grace' end;
    continue when v_m is null;
    -- once per hospital, milestone and end date (paying moves the end date, so the next round starts fresh)
    continue when exists (select 1 from public.notification_outbox o where o.tenant_id = r.id and o.event = 'billing_reminder'
                            and o.vars ->> 'milestone' = v_m and o.vars ->> 'until' = to_char(v_end at time zone 'Asia/Kolkata', 'YYYY-MM-DD'));
    select p.id, p.full_name, p.email into v_prof, v_name, v_mail from public.profiles p where p.tenant_id = r.id and p.role = 'owner' order by p.created_at limit 1;
    v_mail := coalesce(v_mail, (select s.data ->> 'owner_email' from public.app_settings s where s.tenant_id = r.id and s.key = 'bootstrap'));
    continue when v_mail is null and v_prof is null;
    v_link := coalesce((select 'https://' || d.domain || '/billing' from public.tenant_domains d where d.tenant_id = r.id order by d.is_primary desc, (d.verified_at is null), d.created_at limit 1),
                       nullif(rtrim(coalesce((select c.data ->> 'siteUrl' from public.site_content c where c.tenant_id = r.id and c.key = 'settings'), ''), '/') || '/billing', '/billing'),
                       'the app → Billing & plan');
    v_subj := case when v_m = 'grace' then '{hospital}: renew now to keep adding records'
                   when r.lic = 'trial' then '{hospital}: your free trial ends {date}'
                   else '{hospital}: your plan renews {date}' end;
    v_body := case when v_m = 'grace'
      then 'Namaste {name}, the {plan} plan for {hospital} has ended. Everything still works until {read_only}; after that the app becomes read-only until you renew. Renew in a minute: {link}'
      else 'Namaste {name}, the ' || case when r.lic = 'trial' then 'free trial' else '{plan} plan' end
           || ' for {hospital} ends on {date} ({days}). Renew in a minute: {link} — UPI, cards and net banking, with a GST invoice.' end;
    perform set_config('app.tenant_id', r.id::text, true);
    v_count := v_count + public.notify_enqueue_raw('billing_reminder',
      jsonb_build_object('subject', v_subj, 'text', v_body), array['email', 'push'], null, v_mail, v_prof,
      jsonb_build_object('name', split_part(coalesce(v_name, 'there'), ' ', 1), 'milestone', v_m,
        'hospital', coalesce(nullif((select c.data ->> 'name' from public.site_content c where c.tenant_id = r.id and c.key = 'settings'), ''), r.name),
        'until', to_char(v_end at time zone 'Asia/Kolkata', 'YYYY-MM-DD'), 'date', to_char(v_end at time zone 'Asia/Kolkata', 'DD Mon YYYY'),
        'days', case when v_left = 1 then 'tomorrow' else 'in ' || v_left || ' days' end,
        'read_only', to_char((v_end + make_interval(days => coalesce((cfg ->> 'graceDays')::int, 7))) at time zone 'Asia/Kolkata', 'DD Mon YYYY'),
        'plan', initcap(r.plan), 'link', v_link),
      'tenants', r.id, null);
  end loop;
  perform set_config('app.tenant_id', '', true);
  return v_count;
end $$;

-- the owner keeps the name and GSTIN printed on Hospital Comrade's invoices up to date
create or replace function public.set_billing_details(p_legal_name text, p_gstin text, p_address text)
returns void language plpgsql volatile security definer set search_path = public as $$
declare v_gstin text := upper(regexp_replace(coalesce(p_gstin, ''), '\s', '', 'g'));
begin
  if not public.has_role('owner') then raise exception 'Only the owner can change billing details.' using errcode = '42501'; end if;
  if v_gstin <> '' and v_gstin !~ '^[0-9]{2}[A-Z0-9]{10}[0-9A-Z]Z[0-9A-Z]$' then raise exception 'That GSTIN does not look right (15 characters, e.g. 10ABCDE1234F1Z5).'; end if;
  update public.tenants set billing = billing || jsonb_build_object('legalName', left(trim(coalesce(p_legal_name, '')), 150), 'gstin', v_gstin, 'address', left(trim(coalesce(p_address, '')), 300))
   where id = public.current_tenant();
end $$;

-- ------------------------------------------------------------------ platform team tools (until the provider panel)
-- Works on the hospital chosen in the provider banner. admin: everything; finance: manual payments + wallet adjustments.
--   manual_payment  { kind: plan|wallet, months?, amount?, method: bank|upi|cash|cheque, reference?, note? }
--   wallet_adjust   { amount: ±₹, note }            extend_trial { days }            (admin)
--   set_plan        { plan?, price?, included?, ratesPaise? }  (admin; price null = plan price)
--   suspend / resume                                          (admin)
create or replace function public.provider_billing(p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_mode   text := public.provider_mode();
  v_tenant uuid := public.current_tenant();
  q        jsonb;
  v_id     uuid;
  r        jsonb;
  v_amt    numeric;
  cfg      jsonb := public.billing_config();
begin
  if v_mode not in ('admin', 'finance') or not public.provider_can(v_tenant) then
    raise exception 'Only Hospital Comrade admins or finance can do this.' using errcode = '42501';
  end if;
  if p_action in ('extend_trial', 'set_plan', 'suspend', 'resume') and v_mode <> 'admin' then
    raise exception 'Only a Hospital Comrade admin can do this.' using errcode = '42501';
  end if;
  if p_action = 'manual_payment' then
    q := public.billing_quote(v_tenant, p_args ->> 'kind', coalesce((p_args ->> 'months')::int, 1), (p_args ->> 'amount')::numeric, p_args ->> 'plan');
    insert into public.billing_payments (tenant_id, kind, plan, months, base_paise, gst_paise, total_paise, provider, method, payment_id, note,
                                         period_from, period_to, created_by)
    values (v_tenant, q ->> 'kind', q ->> 'plan', (q ->> 'months')::int, (q ->> 'base_paise')::bigint, (q ->> 'gst_paise')::bigint, (q ->> 'total_paise')::bigint,
            'manual', coalesce(nullif(p_args ->> 'method', ''), 'bank'), nullif(p_args ->> 'reference', ''), nullif(p_args ->> 'note', ''),
            (q ->> 'period_from')::date, (q ->> 'period_to')::date, auth.uid())
    returning id into v_id;
    r := public.apply_payment(v_id);
  elsif p_action = 'wallet_adjust' then
    v_amt := (p_args ->> 'amount')::numeric;
    if v_amt is null or v_amt = 0 or abs(v_amt) > 100000 then raise exception 'Enter an amount between -₹1,00,000 and ₹1,00,000.'; end if;
    if coalesce(trim(p_args ->> 'note'), '') = '' then raise exception 'Add a note saying why.'; end if;
    r := jsonb_build_object('wallet_paise', public.wallet_apply(v_tenant, 'adjustment', round(v_amt * 100)::bigint, null, left(p_args ->> 'note', 200)));
  elsif p_action = 'extend_trial' then
    if coalesce((p_args ->> 'days')::int, 0) not between 1 and 90 then raise exception 'Extend by 1 to 90 days.'; end if;
    update public.tenants set trial_ends_at = greatest(now(), coalesce(trial_ends_at, now())) + make_interval(days => (p_args ->> 'days')::int),
                              status = case when status in ('suspended', 'active') then status else 'trial' end
     where id = v_tenant;
  elsif p_action = 'set_plan' then
    if p_args ? 'plan' and not (cfg -> 'plans' ? (p_args ->> 'plan')) then raise exception 'Unknown plan'; end if;
    update public.tenants
       set plan = coalesce(p_args ->> 'plan', plan),
           billing = (billing - 'price' - 'included' - 'ratesPaise')
                     || case when p_args ? 'price' and p_args -> 'price' <> 'null'::jsonb then jsonb_build_object('price', (p_args ->> 'price')::numeric)
                             when not (p_args ? 'price') and billing ? 'price' then jsonb_build_object('price', billing -> 'price') else '{}'::jsonb end
                     || case when p_args ? 'included' then jsonb_build_object('included', p_args -> 'included')
                             when billing ? 'included' then jsonb_build_object('included', billing -> 'included') else '{}'::jsonb end
                     || case when p_args ? 'ratesPaise' then jsonb_build_object('ratesPaise', p_args -> 'ratesPaise')
                             when billing ? 'ratesPaise' then jsonb_build_object('ratesPaise', billing -> 'ratesPaise') else '{}'::jsonb end
     where id = v_tenant;
  elsif p_action = 'suspend' then
    update public.tenants set status = 'suspended' where id = v_tenant and not is_primary;
  elsif p_action = 'resume' then
    update public.tenants set status = case when paid_until > now() then 'active' when trial_ends_at > now() then 'trial' else 'active' end
     where id = v_tenant and status = 'suspended';
  else
    raise exception 'Unknown action %', p_action;
  end if;
  perform public.provider_log('billing:' || p_action, v_tenant::text, p_args);
  return coalesce(r, '{}'::jsonb) || jsonb_build_object('license', public.tenant_license_dates(v_tenant));
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.billing_config(), public.license_guard(), public.wallet_apply(uuid, text, bigint, uuid, text, text, int),
  public.record_message_usage(uuid, text, text, int, int), public.billing_quote(uuid, text, int, numeric, text),
  public.apply_payment(uuid, text, text), public.queue_billing_reminders() from public, anon, authenticated;
grant execute on function public.record_message_usage(uuid, text, text, int, int), public.billing_quote(uuid, text, int, numeric, text),
  public.apply_payment(uuid, text, text), public.queue_billing_reminders() to service_role;
revoke all on function public.billing_summary(), public.my_billing_quote(text, int, numeric, text), public.set_billing_details(text, text, text),
  public.provider_billing(text, jsonb), public.change_trial_plan(text), public.billing_usage_history(int) from public, anon;
grant execute on function public.billing_summary(), public.my_billing_quote(text, int, numeric, text), public.set_billing_details(text, text, text),
  public.provider_billing(text, jsonb), public.change_trial_plan(text), public.billing_usage_history(int) to authenticated;
grant execute on function public.tenant_license(uuid), public.tenant_license_dates(uuid) to anon, authenticated, service_role;


-- =====================================================================================================
--  22. HOSPITAL COMRADE CONTROL PANEL — phase 5 (the separate /control-panel/ app; loaded after billing.sql)
-- =====================================================================================================
--  Every function checks the caller itself (SECURITY DEFINER, explicit provider checks):
--    admin   — every hospital; create / edit hospitals, team, platform settings, audit
--    finance — assigned hospitals; billing actions (manual payments, wallet) and payments
--    support — assigned hospitals; read-only here
--  Acting on one hospital reuses the hospital-scoped functions (provider_billing) with that hospital pinned in the
--  transaction (app.tenant_id), so the same rules and the same provider audit apply.

create or replace function public.cp_require(p_roles text[] default array['admin', 'support', 'finance'])
returns text language plpgsql stable security definer set search_path = public as $$
declare r text := public.provider_role();
begin
  if r is null or not (r = any (p_roles)) then
    raise exception 'Only the Hospital Comrade team (%) can do this.', array_to_string(p_roles, ' / ') using errcode = '42501';
  end if;
  return r;
end $$;

-- who is signed in to the panel (null = not a platform team member)
create or replace function public.cp_me()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('user_id', u.user_id, 'role', u.role, 'email', a.email, 'full_name', coalesce(p.full_name, split_part(a.email, '@', 1)))
    from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id
   where u.user_id = auth.uid() and u.active
$$;

-- ------------------------------------------------------------------ hospitals
create or replace function public.cp_hospitals(p_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  cfg     jsonb := public.billing_config();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
  r       jsonb;
begin
  perform public.cp_require();
  select coalesce(jsonb_agg(h order by h ->> 'is_primary' desc, h ->> 'name'), '[]'::jsonb) into r from (
    select jsonb_build_object(
      'id', t.id, 'slug', t.slug, 'name', t.name, 'code', t.code, 'plan', t.plan, 'is_primary', t.is_primary, 'notes', t.notes,
      'closing_at', t.closing_at, 'purge_after', t.purge_after, 'close_reason', t.close_reason,
      'created_at', t.created_at, 'modules', t.modules, 'license', public.tenant_license_dates(t.id), 'wallet_paise', t.wallet_paise,
      'price', coalesce((t.billing ->> 'price')::numeric, (cfg -> 'plans' -> t.plan ->> 'price')::numeric), 'billing', t.billing,
      'domain', (select d.domain from public.tenant_domains d where d.tenant_id = t.id order by d.is_primary desc, d.created_at limit 1),
      'staff', (select count(*) from public.profiles p where p.tenant_id = t.id and p.role <> 'patient'),
      'patients', (select count(*) from public.patients x where x.tenant_id = t.id),
      'owner_joined', exists (select 1 from public.profiles p where p.tenant_id = t.id and p.role = 'owner'),
      'owner_email', coalesce((select p.email from public.profiles p where p.tenant_id = t.id and p.role = 'owner' order by p.created_at limit 1),
                              (select s.data ->> 'owner_email' from public.app_settings s where s.tenant_id = t.id and s.key = 'bootstrap')),
      'messages', (select coalesce(sum(m.sent), 0) from public.message_usage m where m.tenant_id = t.id and m.month = v_month)
    ) h
    from public.tenants t
    where public.provider_can(t.id) and (p_id is null or t.id = p_id)
  ) q;
  return r;
end $$;

-- one hospital with its domains, team, payments and this month's messages
create or replace function public.cp_hospital(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  h       jsonb;
  v_role  text := public.cp_require();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  h := public.cp_hospitals(p_id) -> 0;
  if h is null then raise exception 'Hospital not found or not assigned to you.'; end if;
  return h || jsonb_build_object(
    'domains', coalesce((select jsonb_agg(jsonb_build_object('domain', d.domain, 'is_primary', d.is_primary, 'method', d.method, 'status', d.status, 'ssl_status', d.ssl_status, 'verified_at', d.verified_at)
                                          order by d.is_primary desc, d.created_at) from public.tenant_domains d where d.tenant_id = p_id), '[]'::jsonb),
    'team', coalesce((select jsonb_agg(jsonb_build_object('user_id', u.user_id, 'role', u.role, 'name', coalesce(p.full_name, a.email)) order by u.role)
                        from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id
                       where u.active and (u.role = 'admin' or exists (select 1 from public.provider_assignments x where x.user_id = u.user_id and x.tenant_id = p_id))), '[]'::jsonb),
    'usage', coalesce((select jsonb_object_agg(m.channel || ':' || m.source, m.sent) from public.message_usage m where m.tenant_id = p_id and m.month = v_month), '{}'::jsonb),
    'payments', case when v_role = 'support' then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(b) - 'tenant_id' - 'buyer' order by b.created_at desc)
                  from (select * from public.billing_payments where tenant_id = p_id and status <> 'created' order by created_at desc limit 20) b), '[]'::jsonb) end);
end $$;

-- a new hospital: tenants row, address, owner e-mail (first sign-up with it becomes the owner), default settings
--   { slug, name, code, plan, owner_email, domain?, status: trial|active, trial_days?, months? (active), modules?, notes? }
-- hospital_create() does the work (internal — also used by self-service sign-up); cp_create_hospital() is the admin's door
create or replace function public.hospital_create(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  cfg     jsonb := public.billing_config();
  v_slug  text := lower(trim(coalesce(p ->> 'slug', '')));
  v_name  text := trim(coalesce(p ->> 'name', ''));
  v_code  text := upper(trim(coalesce(p ->> 'code', '')));
  v_plan  text := coalesce(nullif(p ->> 'plan', ''), 'clinic');
  v_owner text := lower(trim(coalesce(p ->> 'owner_email', '')));
  v_dom   text := lower(trim(regexp_replace(coalesce(p ->> 'domain', ''), '^https?://|/.*$', '', 'g')));
  v_stat  text := coalesce(nullif(p ->> 'status', ''), 'trial');
  v_days  int := coalesce((p ->> 'trial_days')::int, (cfg ->> 'trialDays')::int, 14);
  v_mod   jsonb := coalesce(p -> 'modules', '{"dashboard": "hospital", "forms": "hospital", "notifications": "hospital", "security": "hospital"}'::jsonb);
  v_id    uuid;
begin
  if v_slug !~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$' then raise exception 'Short name: 2–40 characters, a-z, 0-9 and -, e.g. citycare'; end if;
  if char_length(v_name) not between 2 and 120 then raise exception 'Enter the hospital''s name.'; end if;
  if v_code !~ '^[A-Z]{2,6}$' then raise exception 'Record prefix: 2–6 capital letters, e.g. CCC'; end if;
  if not (cfg -> 'plans' ? v_plan) then raise exception 'Unknown plan %', v_plan; end if;
  if v_owner !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter the owner''s e-mail.'; end if;
  if v_stat not in ('trial', 'active') then raise exception 'Start as trial or active.'; end if;
  if v_days not between 1 and 90 then raise exception 'Trial: 1 to 90 days.'; end if;
  if v_dom <> '' and v_dom !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$' then raise exception 'That address does not look like a domain (e.g. citycareclinic.in).'; end if;
  if exists (select 1 from public.tenants where slug = v_slug) then raise exception 'The short name % is taken.', v_slug; end if;
  if v_dom <> '' and exists (select 1 from public.tenant_domains where domain = v_dom) then raise exception '% already belongs to a hospital.', v_dom; end if;
  if exists (select 1 from public.profiles where lower(email) = v_owner and tenant_id is not null and role <> 'patient')
     or exists (select 1 from public.provider_users u join auth.users a on a.id = u.user_id where lower(a.email) = v_owner) then
    raise exception '% is already used by another hospital or the platform team — one account = one hospital, please use another e-mail.', v_owner;
  end if;
  if exists (select 1 from jsonb_each_text(v_mod) m where m.key not in ('general', 'appearance', 'dashboard', 'notifications', 'forms', 'security', 'data', 'cms')
                                                         or m.value not in ('hospital', 'provider')) then
    raise exception 'Unknown module setting';
  end if;

  insert into public.tenants (slug, name, code, plan, status, modules, notes, trial_ends_at, paid_until)
  values (v_slug, v_name, v_code, v_plan, v_stat, v_mod, nullif(trim(coalesce(p ->> 'notes', '')), ''),
          case when v_stat = 'trial' then now() + make_interval(days => v_days) end,
          case when v_stat = 'active' then now() + make_interval(months => greatest(1, least(36, coalesce((p ->> 'months')::int, 12)))) end)
  returning id into v_id;
  perform set_config('app.tenant_id', v_id::text, true);   -- everything below (and its audit trail) belongs to the new hospital
  if v_dom <> '' then insert into public.tenant_domains (domain, tenant_id, is_primary) values (v_dom, v_id, true); end if;
  insert into public.app_settings (tenant_id, key, data) values (v_id, 'bootstrap', jsonb_build_object('owner_email', v_owner));
  perform public.seed_hospital_defaults(v_id);
  perform public.provider_log('hospital:create', v_slug, jsonb_build_object('plan', v_plan, 'status', v_stat, 'owner', v_owner, 'domain', nullif(v_dom, '')));
  return jsonb_build_object('id', v_id, 'slug', v_slug, 'domain', nullif(v_dom, ''), 'owner_email', v_owner);
end $$;

create or replace function public.cp_create_hospital(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return public.hospital_create(p);
end $$;

-- edit a hospital: { name?, code?, notes?, modules?, owner_email? (until the owner has signed up) }
create or replace function public.cp_update_hospital(p_id uuid, p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; v_owner text;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where id = p_id for update;
  if not found then raise exception 'Hospital not found'; end if;
  perform set_config('app.tenant_id', p_id::text, true);
  if p ? 'name' and char_length(trim(p ->> 'name')) not between 2 and 120 then raise exception 'Enter the hospital''s name.'; end if;
  if p ? 'code' and upper(trim(p ->> 'code')) !~ '^[A-Z]{2,6}$' then raise exception 'Record prefix: 2–6 capital letters'; end if;
  if p ? 'modules' and (jsonb_typeof(p -> 'modules') <> 'object' or exists (select 1 from jsonb_each_text(p -> 'modules') m
       where m.key not in ('general', 'appearance', 'dashboard', 'notifications', 'forms', 'security', 'data', 'cms') or m.value not in ('hospital', 'provider'))) then
    raise exception 'Unknown module setting';
  end if;
  update public.tenants set
    name = coalesce(trim(p ->> 'name'), name),
    code = coalesce(upper(trim(p ->> 'code')), code),
    notes = case when p ? 'notes' then nullif(trim(p ->> 'notes'), '') else notes end,
    modules = coalesce(p -> 'modules', modules),
    updated_at = now()
  where id = p_id;
  if p ? 'owner_email' then
    v_owner := lower(trim(p ->> 'owner_email'));
    if v_owner !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter the owner''s e-mail.'; end if;
    if exists (select 1 from public.profiles where tenant_id = p_id and role = 'owner') then raise exception 'The owner has already signed up — change owners in the hospital''s Users & accounts.'; end if;
    insert into public.app_settings (tenant_id, key, data) values (p_id, 'bootstrap', jsonb_build_object('owner_email', v_owner))
    on conflict (tenant_id, key) do update set data = excluded.data;
  end if;
  perform public.provider_log('hospital:update', t.slug, p);
  return public.cp_hospitals(p_id) -> 0;
end $$;

-- plan, trial, wallet, manual payments, suspend for one hospital — the same function the hospital app uses
create or replace function public.cp_billing(p_id uuid, p_action text, p_args jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'finance']);
  if not public.provider_can(p_id) then raise exception 'Hospital not found or not assigned to you.' using errcode = '42501'; end if;
  perform set_config('app.tenant_id', p_id::text, true);
  return public.provider_billing(p_action, coalesce(p_args, '{}'::jsonb));
end $$;

-- ------------------------------------------------------------------ overview
create or replace function public.cp_overview()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_role  text := public.cp_require();
  h       jsonb := public.cp_hospitals();
  v_month date := date_trunc('month', now() at time zone 'Asia/Kolkata')::date;
begin
  return jsonb_build_object(
    'hospitals', jsonb_array_length(h),
    'by_status', coalesce((select jsonb_object_agg(s, n) from (select x -> 'license' ->> 'status' s, count(*) n from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean group by 1) q), '{}'::jsonb),
    'by_plan', coalesce((select jsonb_object_agg(s, n) from (select x ->> 'plan' s, count(*) n from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean group by 1) q), '{}'::jsonb),
    -- monthly recurring revenue: paying hospitals' monthly price (₹, before GST)
    'mrr', coalesce((select sum((x ->> 'price')::numeric) from jsonb_array_elements(h) x where x -> 'license' ->> 'status' = 'active' and not (x ->> 'is_primary')::boolean and x -> 'license' ->> 'paid_until' is not null), 0),
    'wallet_paise', coalesce((select sum((x ->> 'wallet_paise')::bigint) from jsonb_array_elements(h) x where not (x ->> 'is_primary')::boolean), 0),
    'attention', coalesce((select jsonb_agg(jsonb_build_object('id', x -> 'id', 'name', x -> 'name', 'status', x -> 'license' ->> 'status',
                              'until', coalesce(x -> 'license' ->> 'paid_until', x -> 'license' ->> 'trial_ends_at'), 'read_only_from', x -> 'license' ->> 'read_only_from'))
                          from jsonb_array_elements(h) x
                         where not (x ->> 'is_primary')::boolean and (x -> 'license' ->> 'status' in ('grace', 'read_only')
                            or (x -> 'license' ->> 'status' in ('trial', 'active')
                                and coalesce((x -> 'license' ->> 'paid_until')::timestamptz, (x -> 'license' ->> 'trial_ends_at')::timestamptz) < now() + interval '7 days'))), '[]'::jsonb),
    'payments_30d_paise', case when v_role = 'support' then null else
      (select coalesce(sum(total_paise), 0) from public.billing_payments where status = 'paid' and paid_at > now() - interval '30 days' and public.provider_can(tenant_id)) end,
    'messages', coalesce((select jsonb_object_agg(channel, n) from (select m.channel, sum(m.sent) n from public.message_usage m
                           where m.month = v_month and m.source = 'platform' and public.provider_can(m.tenant_id) group by 1) q), '{}'::jsonb),
    'leads_new', case when v_role = 'admin' then (select count(*) from public.platform_leads where status = 'new') end);
end $$;

-- ------------------------------------------------------------------ team
create or replace function public.cp_team()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(jsonb_build_object(
      'user_id', u.user_id, 'email', a.email, 'name', coalesce(p.full_name, split_part(a.email, '@', 1)), 'role', u.role, 'active', u.active, 'since', u.created_at,
      'hospitals', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name) order by t.name) from public.provider_assignments x join public.tenants t on t.id = x.tenant_id where x.user_id = u.user_id), '[]'::jsonb),
      'last_action', (select max(at) from public.provider_audit pa where pa.user_id = u.user_id)) order by u.active desc, u.role, a.email)
    from public.provider_users u join auth.users a on a.id = u.user_id left join public.profiles p on p.id = u.user_id), '[]'::jsonb);
end $$;

-- add / change a team member: { email, role, active, hospitals: [tenant id…] }. They sign up once first (any address).
create or replace function public.cp_save_provider(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_email  text := lower(trim(coalesce(p ->> 'email', '')));
  v_role   text := coalesce(p ->> 'role', 'support');
  v_active boolean := coalesce((p ->> 'active')::boolean, true);
  v_user   uuid;
  v_hosp   text;
begin
  perform public.cp_require(array['admin']);
  if v_role not in ('admin', 'support', 'finance') then raise exception 'Role: admin, support or finance'; end if;
  select id into v_user from auth.users where lower(email) = v_email;
  if v_user is null then raise exception 'No account with % yet — ask them to create one first (Sign up on the platform site), then add them here.', v_email; end if;
  if v_user = auth.uid() and (v_role <> 'admin' or not v_active) then raise exception 'You can''t remove your own admin access — ask another admin.'; end if;
  if not exists (select 1 from public.provider_users where user_id = v_user) then
    select t.name into v_hosp from public.profiles pr join public.tenants t on t.id = pr.tenant_id where pr.id = v_user and pr.role <> 'patient';
    if v_hosp is not null then raise exception '% is a staff account at % — one account = one hospital, please use another e-mail.', v_email, v_hosp; end if;
    -- a platform account belongs to no hospital (its sign-up created a patient record there — removed)
    perform set_config('app.tenant_id', coalesce((select tenant_id::text from public.profiles where id = v_user), ''), true);   -- audit trail stays with that hospital
    perform set_config('app.tenant_move', 'on', true);
    update public.profiles set tenant_id = null, role = 'patient' where id = v_user;
    delete from public.patients where profile_id = v_user;
    perform set_config('app.tenant_move', '', true);
    perform set_config('app.tenant_id', '', true);
  end if;
  insert into public.provider_users (user_id, role, active) values (v_user, v_role, v_active)
  on conflict (user_id) do update set role = excluded.role, active = excluded.active;
  delete from public.provider_assignments where user_id = v_user;
  if v_role <> 'admin' then
    insert into public.provider_assignments (user_id, tenant_id)
    select v_user, t.id from public.tenants t where t.id::text in (select jsonb_array_elements_text(coalesce(p -> 'hospitals', '[]'::jsonb)));
  end if;
  perform public.provider_log('team:save', v_email, jsonb_build_object('role', v_role, 'active', v_active, 'hospitals', p -> 'hospitals'));
  return jsonb_build_object('user_id', v_user);
end $$;

-- ------------------------------------------------------------------ money, audit, settings
create or replace function public.cp_payments(p_tenant uuid default null, p_limit int default 200)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'finance']);
  return coalesce((select jsonb_agg(to_jsonb(b) order by b.created_at desc) from (
    select bp.id, bp.created_at, bp.tenant_id, t.name as hospital, bp.kind, bp.plan, bp.months, bp.base_paise, bp.gst_paise, bp.total_paise,
           bp.status, bp.provider, bp.method, bp.payment_id, bp.order_id, bp.paid_at, bp.invoice_no, bp.period_from, bp.period_to, bp.buyer
      from public.billing_payments bp join public.tenants t on t.id = bp.tenant_id
     where public.provider_can(bp.tenant_id) and (p_tenant is null or bp.tenant_id = p_tenant) and bp.status <> 'created'
     order by bp.created_at desc limit least(greatest(coalesce(p_limit, 200), 1), 1000)) b), '[]'::jsonb);
end $$;

create or replace function public.cp_audit(p_tenant uuid default null, p_limit int default 300)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.at desc) from (
    select pa.id, pa.at, pa.user_name, pa.mode, pa.tenant_id, t.name as hospital, pa.action, pa.target, pa.detail
      from public.provider_audit pa left join public.tenants t on t.id = pa.tenant_id
     where p_tenant is null or pa.tenant_id = p_tenant
     order by pa.at desc limit least(greatest(coalesce(p_limit, 300), 1), 2000)) a), '[]'::jsonb);
end $$;

create or replace function public.cp_settings()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return jsonb_build_object('billing', public.billing_config());
end $$;

-- prices, GST, trial / grace days, message rates, seller details (merged into platform_settings 'billing')
create or replace function public.cp_save_billing_settings(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare k text; n numeric;
begin
  perform public.cp_require(array['admin']);
  if jsonb_typeof(p) <> 'object' then raise exception 'Settings must be an object'; end if;
  for k in select jsonb_object_keys(p) loop
    if k not in ('gstPercent', 'trialDays', 'graceDays', 'yearlyMonths', 'minTopup', 'maxTopup', 'ratesPaise', 'plans', 'seller') then raise exception 'Unknown setting %', k; end if;
  end loop;
  foreach k in array array['gstPercent', 'trialDays', 'graceDays', 'yearlyMonths', 'minTopup', 'maxTopup'] loop
    if p ? k then
      n := (p ->> k)::numeric;
      if n is null or n < 0 or (k = 'gstPercent' and n > 40) or (k in ('trialDays', 'graceDays') and n > 90) or (k = 'yearlyMonths' and (n < 1 or n > 12)) then
        raise exception 'The value for % is out of range.', k;
      end if;
    end if;
  end loop;
  if (p ? 'minTopup' or p ? 'maxTopup')
     and coalesce((p ->> 'minTopup')::numeric, (public.billing_config() ->> 'minTopup')::numeric) > coalesce((p ->> 'maxTopup')::numeric, (public.billing_config() ->> 'maxTopup')::numeric) then
    raise exception 'The minimum top-up is above the maximum.';
  end if;
  if p ? 'ratesPaise' and exists (select 1 from jsonb_each(p -> 'ratesPaise') r where r.key not in ('sms', 'whatsapp', 'email') or jsonb_typeof(r.value) <> 'number' or (r.value)::text::numeric not between 0 and 1000) then
    raise exception 'Message rates: paise per message, 0–1000.';
  end if;
  if p ? 'plans' and exists (select 1 from jsonb_each(p -> 'plans') x where not (public.billing_config() -> 'plans' ? x.key)) then
    raise exception 'Unknown plan';
  end if;
  update public.platform_settings set data = data
    || (p - 'plans' - 'ratesPaise' - 'seller')
    || case when p ? 'ratesPaise' then jsonb_build_object('ratesPaise', coalesce(data -> 'ratesPaise', '{}'::jsonb) || (p -> 'ratesPaise')) else '{}'::jsonb end
    || case when p ? 'seller' then jsonb_build_object('seller', coalesce(data -> 'seller', '{}'::jsonb) || (p -> 'seller')) else '{}'::jsonb end
    || case when p ? 'plans' then jsonb_build_object('plans', (select jsonb_object_agg(e.key, case when p -> 'plans' ? e.key then e.value || (p -> 'plans' -> e.key) else e.value end)
                                                                 from jsonb_each(data -> 'plans') e)) else '{}'::jsonb end
   where key = 'billing';
  perform public.provider_log('settings:billing', null, p);
  return public.billing_config();
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.cp_require(text[]), public.hospital_create(jsonb) from public, anon, authenticated;
revoke all on function public.cp_me(), public.cp_hospitals(uuid), public.cp_hospital(uuid), public.cp_create_hospital(jsonb), public.cp_update_hospital(uuid, jsonb),
  public.cp_billing(uuid, text, jsonb), public.cp_overview(), public.cp_team(), public.cp_save_provider(jsonb), public.cp_payments(uuid, int),
  public.cp_audit(uuid, int), public.cp_settings(), public.cp_save_billing_settings(jsonb) from public, anon;
grant execute on function public.cp_me(), public.cp_hospitals(uuid), public.cp_hospital(uuid), public.cp_create_hospital(jsonb), public.cp_update_hospital(uuid, jsonb),
  public.cp_billing(uuid, text, jsonb), public.cp_overview(), public.cp_team(), public.cp_save_provider(jsonb), public.cp_payments(uuid, int),
  public.cp_audit(uuid, int), public.cp_settings(), public.cp_save_billing_settings(jsonb) to authenticated;


-- =====================================================================================================
--  23. OPS & COMPLIANCE — phase 7 (loaded last, after the control panel)
-- =====================================================================================================
--  7.1 Privacy (DPDP Act 2023): a patient downloads everything held about them, withdraws marketing consent and asks
--      for a correction or erasure; the owner works the requests. Erasure = anonymise: the medical and GST records
--      stay (clinical-establishment and tax rules require them) but nothing identifies the person any more.
--  7.3 Offboarding: the platform closes a hospital (read-only, owner can export), then purges it after the notice
--      period — with a fresh password confirmation ("sudo"). GST invoices to the hospital are archived first.
--  7.4 Incident register (personal-data breaches: Board + affected people within 72 hours).
--  7.5 System health for the platform team.  7.6 Retention: old logs / OTPs / enquiries removed daily.
--  Session switches used here: app.skip_audit (no copy of removed data in the audit log), app.privacy (privacy
--  actions pass the licence guard). Only SECURITY DEFINER functions set them.

-- ------------------------------------------------------------------ helpers
-- did the signed-in user type their password in the last p_seconds? (Supabase puts the sign-in time in the JWT's amr)
create or replace function public.recent_reauth(p_seconds int default 600)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare c jsonb; v_ts numeric;
begin
  begin c := nullif(current_setting('request.jwt.claims', true), '')::jsonb; exception when others then c := null; end;
  if c is null then return false; end if;
  select max((a ->> 'timestamp')::numeric) into v_ts from jsonb_array_elements(case when jsonb_typeof(c -> 'amr') = 'array' then c -> 'amr' else '[]'::jsonb end) a
   where a ->> 'method' in ('password', 'otp', 'totp');
  v_ts := coalesce(v_ts, (c ->> 'iat')::numeric);
  return v_ts is not null and to_timestamp(v_ts) > now() - make_interval(secs => greatest(coalesce(p_seconds, 600), 60));
end $$;

-- the hospital owner to write to (the first owner account, else the e-mail the owner will sign up with)
create or replace function public.tenant_owner_contact(p_tenant uuid)
returns table (profile_id uuid, full_name text, email text) language sql stable security definer set search_path = public as $$
  select p.id, p.full_name, p.email from public.profiles p where p.tenant_id = p_tenant and p.role = 'owner'
  union all
  select null, null, s.data ->> 'owner_email' from public.app_settings s
   where s.tenant_id = p_tenant and s.key = 'bootstrap' and not exists (select 1 from public.profiles p where p.tenant_id = p_tenant and p.role = 'owner')
  limit 1
$$;

-- ------------------------------------------------------------------ 7.1 privacy: tables
alter table public.patients add column if not exists marketing_opt_out boolean not null default false;
alter table public.patients add column if not exists erased_at timestamptz;

create table if not exists public.privacy_requests (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at        timestamptz not null default now(),
  profile_id        uuid references public.profiles (id) on delete set null,
  patient_id        uuid references public.patients (id) on delete set null,
  requester_name    text,
  kind              text not null check (kind in ('access', 'correction', 'erasure')),
  details           text check (char_length(details) <= 2000),
  status            text not null default 'open' check (status in ('open', 'done', 'rejected')),
  resolved_at       timestamptz,
  resolved_by       uuid,
  resolved_by_name  text,
  resolution        text check (char_length(resolution) <= 1000)
);
create index if not exists privacy_requests_tenant_idx on public.privacy_requests (tenant_id, status, created_at desc);

create table if not exists public.consent_log (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null default public.current_tenant() references public.tenants (id) on delete cascade,
  created_at  timestamptz not null default now(),
  profile_id  uuid references public.profiles (id) on delete set null,
  patient_id  uuid references public.patients (id) on delete set null,
  purpose     text not null,                       -- 'marketing' (health tips & offers)
  granted     boolean not null,
  source      text not null default 'portal'
);
create index if not exists consent_log_patient_idx on public.consent_log (tenant_id, patient_id, created_at desc);

do $rls$
declare t text;
begin
  foreach t in array array['privacy_requests', 'consent_log'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('drop policy if exists tenant_isolation on public.%I', t);
    execute format('create policy tenant_isolation on public.%I as restrictive for all to anon, authenticated
                      using (tenant_id = (select public.current_tenant())) with check (tenant_id = (select public.current_tenant()))', t);
    execute format('drop policy if exists privacy_read on public.%I', t);
    -- the person themself, and the owner who answers the requests
    execute format('create policy privacy_read on public.%I for select to authenticated using (profile_id = (select auth.uid()) or public.has_role(''owner''))', t);
    execute format('drop trigger if exists trg_keep_tenant on public.%I', t);
    execute format('create trigger trg_keep_tenant before update of tenant_id on public.%I for each row execute function public.keep_tenant()', t);
  end loop;
end $rls$;

-- scheduled / custom messages to patients skip those who said no to health tips & offers
create or replace function public.patient_accepts_marketing(p_patient uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce((select not marketing_opt_out and erased_at is null from public.patients where id = p_patient), true)
$$;

-- ------------------------------------------------------------------ 7.1 privacy: the patient
-- everything this hospital holds about the signed-in person, as one JSON document (logged as a fulfilled access request)
create or replace function public.my_data_export()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_pid uuid;
  r     jsonb;
  t     text;
  rows  jsonb;
begin
  if v_uid is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  select id into v_pid from public.patients where profile_id = v_uid and tenant_id = public.current_tenant();
  r := jsonb_build_object(
    'generated_at', now(),
    'hospital', (select name from public.tenants where id = public.current_tenant()),
    'account', (select to_jsonb(p) - 'tenant_id' from public.profiles p where p.id = v_uid),
    'patient', (select to_jsonb(x) - 'tenant_id' from public.patients x where x.id = v_pid));
  if v_pid is not null then
    foreach t in array array['appointments', 'prescriptions', 'lab_tests', 'admissions', 'invoices', 'payments', 'visit_feedback'] loop
      continue when to_regclass('public.' || t) is null;
      execute format('select coalesce(jsonb_agg(to_jsonb(x) - ''tenant_id'' order by x.created_at), ''[]''::jsonb) from public.%I x where x.patient_id = $1 and x.tenant_id = $2', t)
        into rows using v_pid, public.current_tenant();
      r := r || jsonb_build_object(t, rows);
    end loop;
  end if;
  r := r || jsonb_build_object(
    'consents', coalesce((select jsonb_agg(jsonb_build_object('at', c.created_at, 'purpose', c.purpose, 'granted', c.granted, 'source', c.source) order by c.created_at)
                            from public.consent_log c where c.profile_id = v_uid and c.tenant_id = public.current_tenant()), '[]'::jsonb),
    'requests', coalesce((select jsonb_agg(jsonb_build_object('at', q.created_at, 'kind', q.kind, 'status', q.status, 'details', q.details, 'resolution', q.resolution) order by q.created_at)
                            from public.privacy_requests q where q.profile_id = v_uid and q.tenant_id = public.current_tenant()), '[]'::jsonb));
  perform set_config('app.privacy', 'on', true);
  insert into public.privacy_requests (profile_id, patient_id, requester_name, kind, details, status, resolved_at, resolution)
  values (v_uid, v_pid, (select full_name from public.profiles where id = v_uid), 'access', 'Downloaded from the patient portal', 'done', now(), 'Self-service download');
  perform set_config('app.privacy', '', true);
  return r;
end $$;

-- marketing (health tips & offers) consent — appointment and health messages are part of the service and always sent
create or replace function public.set_marketing_consent(p_granted boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_pid uuid;
begin
  if auth.uid() is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  select id into v_pid from public.patients where profile_id = auth.uid() and tenant_id = public.current_tenant();
  if v_pid is null then raise exception 'Only patients have this choice.'; end if;
  perform set_config('app.privacy', 'on', true);
  update public.patients set marketing_opt_out = not coalesce(p_granted, false), updated_at = now() where id = v_pid;
  insert into public.consent_log (profile_id, patient_id, purpose, granted, source) values (auth.uid(), v_pid, 'marketing', coalesce(p_granted, false), 'portal');
  perform set_config('app.privacy', '', true);
  return jsonb_build_object('marketing', coalesce(p_granted, false));
end $$;

-- ask the hospital to correct or erase my data (one open request of each kind); the owner is e-mailed
create or replace function public.privacy_submit(p_kind text, p_details text default null)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid; v_pid uuid; v_name text; o record;
begin
  if auth.uid() is null then raise exception 'Sign in first.' using errcode = '42501'; end if;
  if p_kind not in ('correction', 'erasure') then raise exception 'Choose correction or erasure.'; end if;
  if p_kind = 'correction' and coalesce(trim(p_details), '') = '' then raise exception 'Tell us what is wrong and what it should say.'; end if;
  if exists (select 1 from public.privacy_requests where profile_id = auth.uid() and kind = p_kind and status = 'open' and tenant_id = public.current_tenant()) then
    raise exception 'You already have an open % request — the hospital will get back to you.', p_kind;
  end if;
  select id into v_pid from public.patients where profile_id = auth.uid() and tenant_id = public.current_tenant();
  select full_name into v_name from public.profiles where id = auth.uid();
  perform set_config('app.privacy', 'on', true);
  insert into public.privacy_requests (profile_id, patient_id, requester_name, kind, details)
  values (auth.uid(), v_pid, v_name, p_kind, nullif(left(trim(coalesce(p_details, '')), 2000), '')) returning id into v_id;
  perform set_config('app.privacy', '', true);
  select * into o from public.tenant_owner_contact(public.current_tenant());
  if o.email is not null or o.profile_id is not null then
    perform public.notify_enqueue_raw('privacy_request',
      jsonb_build_object('subject', '{hospital}: new privacy request ({kind})',
        'text', 'A patient ({name}) asked for data {kind}. Please answer within 30 days: Privacy requests in the app.'),
      array['email', 'push'], null, o.email, o.profile_id, jsonb_build_object('kind', p_kind, 'name', coalesce(v_name, 'patient')), 'privacy_requests', v_id);
  end if;
  return v_id;
end $$;

-- ------------------------------------------------------------------ 7.1 privacy: erasure (anonymisation)
create or replace function public.erase_patient(p_patient uuid, p_reason text default null)
returns void language plpgsql volatile security definer set search_path = public as $$
declare p public.patients; v_phone text;
begin
  select * into p from public.patients where id = p_patient for update;
  if not found then raise exception 'Patient not found'; end if;
  if p.erased_at is not null then return; end if;
  v_phone := right(regexp_replace(coalesce(p.phone, ''), '\D', '', 'g'), 10);
  perform set_config('app.skip_audit', 'on', true);
  perform set_config('app.privacy', 'on', true);
  update public.patients
     set full_name = 'Erased patient ' || p.mrn, phone = null, email = null, address = null, emergency_contact_name = null,
         emergency_contact_phone = null, insurance_provider = null,
         date_of_birth = case when p.date_of_birth is null then null else make_date(extract(year from p.date_of_birth)::int, 1, 1) end,
         marketing_opt_out = true, erased_at = now(), profile_id = null, updated_at = now()
   where id = p.id;
  update public.visit_feedback set comment = null where patient_id = p.id;
  if v_phone <> '' then
    delete from public.wa_sessions where right(regexp_replace(phone, '\D', '', 'g'), 10) = v_phone and tenant_id = p.tenant_id;
    delete from public.booking_otps where right(regexp_replace(phone, '\D', '', 'g'), 10) = v_phone and tenant_id = p.tenant_id;
    delete from public.site_enquiries where right(regexp_replace(phone, '\D', '', 'g'), 10) = v_phone and tenant_id = p.tenant_id;
  end if;
  -- the sign-in account goes (profile, devices, consents follow); clinical rows keep pointing at the anonymised patient
  if p.profile_id is not null then delete from auth.users where id = p.profile_id; end if;
  -- the audit trail keeps that something happened, not who it was about
  update public.audit_log set changes = jsonb_build_object('redacted', true), summary = 'Erased patient ' || p.mrn
   where record_id in (p.id, coalesce(p.profile_id, p.id));
  insert into public.audit_log (table_name, record_id, action, actor_id, actor_name, actor_role, summary, changes)
  values ('patients', p.id, 'update', auth.uid(), coalesce((select full_name from public.profiles where id = auth.uid()), 'System'),
          coalesce((select role::text from public.profiles where id = auth.uid()), 'system'), 'Erased patient ' || p.mrn,
          jsonb_build_object('erased', jsonb_build_object('to', true), 'reason', jsonb_build_object('to', left(coalesce(p_reason, 'privacy request'), 200))));
  perform set_config('app.skip_audit', '', true);
  perform set_config('app.privacy', '', true);
end $$;

-- the owner answers a request: done / rejected (+ a note to the person). Erasure "done" anonymises the patient.
create or replace function public.privacy_resolve(p_id uuid, p_status text, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare q public.privacy_requests;
begin
  if not public.has_role('owner') then raise exception 'Only the owner answers privacy requests.' using errcode = '42501'; end if;
  if p_status not in ('done', 'rejected') then raise exception 'Mark it done or rejected.'; end if;
  select * into q from public.privacy_requests where id = p_id and tenant_id = public.current_tenant() for update;
  if not found then raise exception 'Request not found'; end if;
  if q.status <> 'open' then raise exception 'This request was already answered.'; end if;
  if p_status = 'rejected' and coalesce(trim(p_note), '') = '' then raise exception 'Say why — the person sees this note.'; end if;
  if q.kind = 'erasure' and p_status = 'done' then
    if q.patient_id is not null then perform public.erase_patient(q.patient_id, 'privacy request');
    elsif q.profile_id is not null then delete from auth.users where id = q.profile_id; end if;
  end if;
  perform set_config('app.privacy', 'on', true);
  update public.privacy_requests set status = p_status, resolved_at = now(), resolved_by = auth.uid(),
         resolved_by_name = (select full_name from public.profiles where id = auth.uid()), resolution = nullif(left(trim(coalesce(p_note, '')), 1000), '')
   where id = p_id;
  perform set_config('app.privacy', '', true);
  return (select to_jsonb(r) from public.privacy_requests r where r.id = p_id);
end $$;

-- ------------------------------------------------------------------ 7.3 offboarding
create table if not exists public.tenant_purges (
  id              uuid primary key default gen_random_uuid(),
  hospital_id     uuid not null,          -- not "tenant_id": this platform table must stay out of the per-hospital loops
  slug            text not null,
  name            text not null,
  closed_at       timestamptz,
  close_reason    text,
  purged_at       timestamptz not null default now(),
  purged_by       uuid,
  purged_by_name  text,
  counts          jsonb not null default '{}'::jsonb,
  billing         jsonb not null default '[]'::jsonb      -- the platform's GST invoices to the hospital (kept 8 years)
);
alter table public.tenant_purges enable row level security;
revoke all on public.tenant_purges from anon, authenticated;
grant all on public.tenant_purges to service_role;

create or replace function public.cp_close_hospital(p_id uuid, p_reason text, p_days int default 30)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants; o record;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where id = p_id for update;
  if not found then raise exception 'Hospital not found'; end if;
  if t.is_primary then raise exception 'The platform''s own hospital can''t be closed.'; end if;
  if t.closing_at is not null then raise exception 'This hospital is already closing.'; end if;
  if coalesce(p_days, 0) not between 7 and 90 then raise exception 'Give the hospital 7 to 90 days to export its data.'; end if;
  if coalesce(trim(p_reason), '') = '' then raise exception 'Add the reason (it is kept with the record).'; end if;
  update public.tenants set closing_at = now(), purge_after = now() + make_interval(days => p_days), close_reason = left(trim(p_reason), 300), updated_at = now() where id = p_id;
  perform set_config('app.tenant_id', p_id::text, true);
  perform public.provider_log('hospital:close', t.slug, jsonb_build_object('reason', p_reason, 'days', p_days));
  select * into o from public.tenant_owner_contact(p_id);
  if o.email is not null or o.profile_id is not null then
    perform public.notify_enqueue_raw('hospital_closing',
      jsonb_build_object('subject', '{hospital}: your account is closing on {date}',
        'text', 'Your Hospital Comrade account for {hospital} is now read-only and will be deleted after {date}. Download your data before then: Settings → Data → Export all data.'),
      array['email', 'push'], null, o.email, o.profile_id,
      jsonb_build_object('date', to_char((now() + make_interval(days => p_days)) at time zone 'Asia/Kolkata', 'DD Mon YYYY')), 'tenants', p_id);
  end if;
  return public.cp_hospital(p_id);
end $$;

create or replace function public.cp_reopen_hospital(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare t public.tenants;
begin
  perform public.cp_require(array['admin']);
  select * into t from public.tenants where id = p_id for update;
  if not found or t.closing_at is null then raise exception 'This hospital is not closing.'; end if;
  update public.tenants set closing_at = null, purge_after = null, close_reason = null, updated_at = now() where id = p_id;
  perform set_config('app.tenant_id', p_id::text, true);
  perform public.provider_log('hospital:reopen', t.slug, null);
  return public.cp_hospital(p_id);
end $$;

-- delete everything of a closed hospital. Needs: admin, password typed in the last 10 minutes, the short name typed,
-- the notice period over. Keeps a tombstone with row counts and the platform's invoices to the hospital.
create or replace function public.cp_purge_hospital(p_id uuid, p_confirm text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  t       public.tenants;
  v_tabs  text[];
  v_left  text[];
  tab     text;
  v_pass  int := 0;
  v_count jsonb := '{}'::jsonb;
  n       bigint;
begin
  perform public.cp_require(array['admin']);
  if not public.recent_reauth(600) then
    raise exception 'REAUTH_REQUIRED: Confirm your password to delete a hospital.' using errcode = '42501';
  end if;
  select * into t from public.tenants where id = p_id for update;
  if not found then raise exception 'Hospital not found'; end if;
  if t.is_primary then raise exception 'The platform''s own hospital can''t be deleted.'; end if;
  if t.closing_at is null then raise exception 'Close the hospital first — it gets time to export its data.'; end if;
  if t.purge_after > now() then raise exception 'The hospital can export its data until % — delete after that.', to_char(t.purge_after at time zone 'Asia/Kolkata', 'DD Mon YYYY'); end if;
  if coalesce(p_confirm, '') <> t.slug then raise exception 'Type the hospital''s short name (%) to confirm.', t.slug; end if;

  perform set_config('app.tenant_id', p_id::text, true);
  perform set_config('app.skip_audit', 'on', true);
  select array_agg(c.table_name::text order by c.table_name) into v_tabs
    from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
   where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name not in ('tenants', 'provider_audit');
  foreach tab in array v_tabs loop
    execute format('select count(*) from public.%I where tenant_id = $1', tab) into n using p_id;
    if n > 0 then v_count := v_count || jsonb_build_object(tab, n); end if;
  end loop;
  insert into public.tenant_purges (hospital_id, slug, name, closed_at, close_reason, purged_by, purged_by_name, counts, billing)
  values (t.id, t.slug, t.name, t.closing_at, t.close_reason, auth.uid(), (select full_name from public.profiles where id = auth.uid()), v_count,
          coalesce((select jsonb_agg(to_jsonb(b) order by b.created_at) from public.billing_payments b where b.tenant_id = p_id and b.status in ('paid', 'refunded')), '[]'::jsonb));

  -- sign-in accounts first (a person belongs to one hospital), then the rows: tables referencing each other with
  -- ON DELETE RESTRICT are emptied children-first by retrying until nothing is left
  delete from auth.users where id in (select id from public.profiles where tenant_id = p_id) and id not in (select user_id from public.provider_users);
  v_left := v_tabs;
  while array_length(v_left, 1) > 0 and v_pass < 8 loop
    v_pass := v_pass + 1;
    v_tabs := v_left; v_left := '{}';
    foreach tab in array v_tabs loop
      begin
        execute format('delete from public.%I where tenant_id = $1', tab) using p_id;
      exception when foreign_key_violation or restrict_violation then v_left := v_left || tab;
      end;
    end loop;
  end loop;
  if array_length(v_left, 1) > 0 then raise exception 'Could not delete: %', array_to_string(v_left, ', '); end if;
  delete from public.tenants where id = p_id;
  perform set_config('app.skip_audit', '', true);
  perform public.provider_log('hospital:purge', t.slug, jsonb_build_object('name', t.name, 'counts', v_count));
  return jsonb_build_object('purged', t.slug, 'counts', v_count);
end $$;

-- ------------------------------------------------------------------ 7.4 incident register
create table if not exists public.platform_incidents (
  id                     uuid primary key default gen_random_uuid(),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  detected_at            timestamptz not null default now(),
  title                  text not null check (char_length(title) between 3 and 200),
  description            text check (char_length(description) <= 5000),
  severity               text not null default 'medium' check (severity in ('low', 'medium', 'high', 'critical')),
  status                 text not null default 'open' check (status in ('open', 'contained', 'resolved')),
  personal_data          boolean not null default false,
  affected_tenants       uuid[] not null default '{}',
  affected_people        int check (affected_people >= 0),
  board_reported_at      timestamptz,
  hospitals_notified_at  timestamptz,
  resolved_at            timestamptz,
  timeline               jsonb not null default '[]'::jsonb,
  created_by             uuid,
  created_by_name        text
);
alter table public.platform_incidents enable row level security;
revoke all on public.platform_incidents from anon, authenticated;
grant all on public.platform_incidents to service_role;

create or replace function public.cp_incidents()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin', 'support']);
  return coalesce((select jsonb_agg(to_jsonb(i) || jsonb_build_object(
      'deadline', i.detected_at + interval '72 hours',
      'hospitals', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'slug', t.slug) order by t.name) from public.tenants t where t.id = any (i.affected_tenants)), '[]'::jsonb))
      order by (i.status = 'resolved'), i.detected_at desc)
    from public.platform_incidents i), '[]'::jsonb);
end $$;

-- create (no id) or update an incident; "note" appends to the timeline; board_reported: true stamps the time
create or replace function public.cp_save_incident(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v_id uuid := nullif(p ->> 'id', '')::uuid; v_name text := (select full_name from public.profiles where id = auth.uid()); i public.platform_incidents;
begin
  perform public.cp_require(array['admin']);
  if v_id is null then
    insert into public.platform_incidents (title, description, severity, personal_data, affected_tenants, affected_people, detected_at, created_by, created_by_name, timeline)
    values (trim(p ->> 'title'), p ->> 'description', coalesce(p ->> 'severity', 'medium'), coalesce((p ->> 'personal_data')::boolean, false),
            coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(p -> 'affected_tenants', '[]'::jsonb)) x), '{}'),
            (p ->> 'affected_people')::int, coalesce((p ->> 'detected_at')::timestamptz, now()), auth.uid(), v_name,
            jsonb_build_array(jsonb_build_object('at', now(), 'by', v_name, 'note', coalesce(nullif(p ->> 'note', ''), 'Incident recorded'))))
    returning id into v_id;
  else
    select * into i from public.platform_incidents where id = v_id for update;
    if not found then raise exception 'Incident not found'; end if;
    update public.platform_incidents set
      title = coalesce(nullif(trim(p ->> 'title'), ''), title),
      description = case when p ? 'description' then p ->> 'description' else description end,
      severity = coalesce(p ->> 'severity', severity),
      status = coalesce(p ->> 'status', status),
      personal_data = coalesce((p ->> 'personal_data')::boolean, personal_data),
      affected_tenants = case when p ? 'affected_tenants' then coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(p -> 'affected_tenants') x), '{}') else affected_tenants end,
      affected_people = case when p ? 'affected_people' then (p ->> 'affected_people')::int else affected_people end,
      board_reported_at = case when coalesce((p ->> 'board_reported')::boolean, false) then coalesce(board_reported_at, now()) else board_reported_at end,
      resolved_at = case when p ->> 'status' = 'resolved' then coalesce(resolved_at, now()) when p ->> 'status' in ('open', 'contained') then null else resolved_at end,
      timeline = timeline || case when coalesce(p ->> 'note', '') <> '' or (p ->> 'status') is distinct from i.status and p ? 'status'
                                  then jsonb_build_array(jsonb_build_object('at', now(), 'by', v_name,
                                         'note', concat_ws(' — ', case when p ? 'status' and (p ->> 'status') <> i.status then 'Status: ' || (p ->> 'status') end, nullif(p ->> 'note', ''))))
                                  else '[]'::jsonb end,
      updated_at = now()
     where id = v_id;
  end if;
  perform public.provider_log('incident:save', v_id::text, p - 'description');
  return (select to_jsonb(x) from public.platform_incidents x where x.id = v_id);
end $$;

-- e-mail (+ push) the owners of the affected hospitals; returns who got it queued and who must be contacted by hand
create or replace function public.cp_notify_incident(p_id uuid, p_message text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare i public.platform_incidents; t record; o record; n int; r jsonb := '[]'::jsonb;
begin
  perform public.cp_require(array['admin']);
  select * into i from public.platform_incidents where id = p_id for update;
  if not found then raise exception 'Incident not found'; end if;
  if coalesce(trim(p_message), '') = '' then raise exception 'Write the notice: what happened, what data, what you are doing, what they should do.'; end if;
  if cardinality(i.affected_tenants) = 0 then raise exception 'Add the affected hospitals first.'; end if;
  for t in select id, name from public.tenants where id = any (i.affected_tenants) order by name loop
    perform set_config('app.tenant_id', t.id::text, true);
    select * into o from public.tenant_owner_contact(t.id);
    n := 0;
    if o.email is not null or o.profile_id is not null then
      n := public.notify_enqueue_raw('incident_notice', jsonb_build_object('subject', '{hospital}: security notice from Hospital Comrade', 'text', left(p_message, 3500)),
             array['email', 'push'], null, o.email, o.profile_id, jsonb_build_object('incident', i.id), 'platform_incidents', i.id);
    end if;
    r := r || jsonb_build_object('id', t.id, 'name', t.name, 'owner_email', o.email, 'queued', n);
  end loop;
  perform set_config('app.tenant_id', '', true);
  update public.platform_incidents set hospitals_notified_at = now(), updated_at = now(),
         timeline = timeline || jsonb_build_array(jsonb_build_object('at', now(), 'by', (select full_name from public.profiles where id = auth.uid()),
                                                                      'note', 'Hospitals notified (' || jsonb_array_length(r) || ')'))
   where id = p_id;
  perform public.provider_log('incident:notify', p_id::text, jsonb_build_object('hospitals', r));
  return r;
end $$;

-- ------------------------------------------------------------------ 7.6 retention
insert into public.platform_settings (key, data) values ('retention', jsonb_build_object(
  'auditDays', 1095, 'providerAuditDays', 1095, 'outboxDays', 400, 'otpDays', 7, 'enquiryDays', 1095, 'leadDays', 1095,
  'privacyDays', 1095, 'waSessionDays', 30))
on conflict (key) do nothing;

create or replace function public.retention_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select data from public.platform_settings where key = 'retention'), '{}'::jsonb)
$$;

-- delete what is past its keep-by date (daily from the scheduler as dch-retention; a platform admin can run it too)
create or replace function public.run_retention()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c   jsonb := public.retention_config();
  r   jsonb := '{}'::jsonb;
  r_s jsonb;
  n   bigint;
  d   int;
begin
  if auth.uid() is not null and coalesce(public.provider_role(), '') <> 'admin' then raise exception 'Not allowed' using errcode = '42501'; end if;
  perform set_config('app.skip_audit', 'on', true);
  d := greatest(coalesce((c ->> 'auditDays')::int, 1095), 365);
  delete from public.audit_log where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('audit_log', n);
  d := greatest(coalesce((c ->> 'providerAuditDays')::int, 1095), 365);
  delete from public.provider_audit where at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('provider_audit', n);
  d := greatest(coalesce((c ->> 'outboxDays')::int, 400), 30);
  delete from public.notification_outbox where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('notification_outbox', n);
  d := greatest(coalesce((c ->> 'otpDays')::int, 7), 1);
  delete from public.booking_otps where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('booking_otps', n);
  delete from public.password_reset_otps where created_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('password_reset_otps', n);
  d := greatest(coalesce((c ->> 'enquiryDays')::int, 1095), 30);
  delete from public.site_enquiries where created_at < now() - make_interval(days => d) and status in ('resolved', 'spam'); get diagnostics n = row_count; r := r || jsonb_build_object('site_enquiries', n);
  d := greatest(coalesce((c ->> 'leadDays')::int, 1095), 30);
  delete from public.platform_leads where created_at < now() - make_interval(days => d) and status in ('won', 'lost'); get diagnostics n = row_count; r := r || jsonb_build_object('platform_leads', n);
  d := greatest(coalesce((c ->> 'privacyDays')::int, 1095), 365);
  delete from public.privacy_requests where status <> 'open' and resolved_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('privacy_requests', n);
  d := greatest(coalesce((c ->> 'waSessionDays')::int, 30), 1);
  delete from public.wa_sessions where updated_at < now() - make_interval(days => d); get diagnostics n = row_count; r := r || jsonb_build_object('wa_sessions', n);
  -- self-service sign-ups (phase 8, signup.sql — loaded after this file)
  if to_regprocedure('public.signup_cleanup()') is not null then execute 'select public.signup_cleanup()' into r_s; r := r || jsonb_build_object('signups', r_s); end if;
  perform set_config('app.skip_audit', '', true);
  update public.platform_settings set data = data || jsonb_build_object('last_run', jsonb_build_object('at', now(), 'deleted', r)), updated_at = now() where key = 'retention';
  return r;
end $$;

create or replace function public.cp_retention()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return public.retention_config();
end $$;

create or replace function public.cp_save_retention(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare k text; v int;
  mins constant jsonb := '{"auditDays": 365, "providerAuditDays": 365, "outboxDays": 30, "otpDays": 1, "enquiryDays": 30, "leadDays": 30, "privacyDays": 365, "waSessionDays": 1}';
begin
  perform public.cp_require(array['admin']);
  for k in select jsonb_object_keys(coalesce(p, '{}'::jsonb)) loop
    if not (mins ? k) then raise exception 'Unknown setting %', k; end if;
    v := (p ->> k)::int;
    if v is null or v < (mins ->> k)::int or v > 3650 then raise exception '%: keep at least % days (at most 3650).', k, mins ->> k; end if;
  end loop;
  update public.platform_settings set data = data || (select jsonb_object_agg(key, (value #>> '{}')::int) from jsonb_each(p)), updated_at = now() where key = 'retention';
  perform public.provider_log('settings:retention', null, p);
  return public.retention_config();
end $$;

-- ------------------------------------------------------------------ 7.5 system health
create or replace function public.cp_health()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_role text := public.cp_require(array['admin', 'support']);
  v_cron boolean := exists (select 1 from pg_extension where extname = 'pg_cron');
  v_net  boolean := exists (select 1 from pg_extension where extname = 'pg_net');
  v_jobs jsonb := '[]'::jsonb;
  v_db   bigint;
begin
  if v_cron then
    execute $q$ select coalesce(jsonb_agg(jsonb_build_object('name', j.jobname, 'schedule', j.schedule, 'active', j.active,
              'last_run', d.start_time, 'last_status', d.status, 'last_message', left(d.return_message, 200)) order by j.jobname), '[]'::jsonb)
           from cron.job j
           left join lateral (select start_time, status, return_message from cron.job_run_details r where r.jobid = j.jobid order by start_time desc limit 1) d on true
          where j.jobname like 'dch-%' $q$ into v_jobs;
  end if;
  begin v_db := pg_database_size(current_database()); exception when others then v_db := null; end;
  return jsonb_build_object(
    'at', now(),
    'extensions', jsonb_build_object('pg_cron', v_cron, 'pg_net', v_net),
    'jobs', v_jobs,
    'messages', coalesce((select jsonb_agg(x order by (x ->> 'failed')::int desc, x ->> 'name') from (
        select jsonb_build_object('id', t.id, 'name', t.name,
          'sent', count(*) filter (where o.status = 'sent'), 'failed', count(*) filter (where o.status = 'failed'),
          'waiting', count(*) filter (where o.status in ('queued', 'sending')),
          'stuck', count(*) filter (where o.status in ('queued', 'sending') and o.created_at < now() - interval '15 minutes')) x
          from public.notification_outbox o join public.tenants t on t.id = o.tenant_id
         where o.created_at > now() - interval '24 hours' and (v_role = 'admin' or public.provider_can(t.id))
         group by t.id, t.name) s), '[]'::jsonb),
    'recent_failures', coalesce((select jsonb_agg(jsonb_build_object('at', o.created_at, 'hospital', t.name, 'event', o.event, 'channel', o.channel, 'error', left(o.error, 200)) order by o.created_at desc)
        from (select * from public.notification_outbox where status = 'failed' and created_at > now() - interval '7 days' order by created_at desc limit 20) o
        join public.tenants t on t.id = o.tenant_id where v_role = 'admin' or public.provider_can(t.id)), '[]'::jsonb),
    'payments', jsonb_build_object(
        'abandoned_7d', (select count(*) from public.billing_payments where status = 'created' and created_at between now() - interval '7 days' and now() - interval '1 hour'),
        'failed_7d', (select count(*) from public.billing_payments where status = 'failed' and created_at > now() - interval '7 days'),
        'paid_7d', (select count(*) from public.billing_payments where status = 'paid' and paid_at > now() - interval '7 days')),
    'database', jsonb_build_object('size_bytes', v_db,
        'largest_tables', case when v_role = 'admin' then coalesce((select jsonb_agg(jsonb_build_object('table', c.relname, 'bytes', pg_total_relation_size(c.oid)) order by pg_total_relation_size(c.oid) desc)
            from (select c.oid, c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r'
                  order by pg_total_relation_size(c.oid) desc limit 8) c), '[]'::jsonb) else '[]'::jsonb end),
    'hospitals', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'closing_at', t.closing_at, 'purge_after', t.purge_after,
          'patients', (select count(*) from public.patients p where p.tenant_id = t.id),
          'appointments', (select count(*) from public.appointments a where a.tenant_id = t.id),
          'invoices', (select count(*) from public.invoices i where i.tenant_id = t.id),
          'audit_log', (select count(*) from public.audit_log l where l.tenant_id = t.id)) order by t.is_primary desc, t.name)
        from public.tenants t where v_role = 'admin' or public.provider_can(t.id)), '[]'::jsonb),
    'retention', public.retention_config() -> 'last_run',
    'privacy_open', (select count(*) from public.privacy_requests where status = 'open'),
    'privacy_overdue', (select count(*) from public.privacy_requests where status = 'open' and created_at < now() - interval '30 days'),
    'incidents_open', (select count(*) from public.platform_incidents where status <> 'resolved'));
end $$;

-- ------------------------------------------------------------------ who may call what
revoke all on function public.recent_reauth(int), public.tenant_owner_contact(uuid), public.erase_patient(uuid, text),
  public.retention_config(), public.patient_accepts_marketing(uuid) from public, anon, authenticated;
grant execute on function public.run_retention(), public.patient_accepts_marketing(uuid) to service_role;
-- run_retention checks the caller itself (scheduler / service, or a platform admin from the panel)
revoke all on function public.run_retention() from public, anon;
grant execute on function public.run_retention() to authenticated;
revoke all on function public.my_data_export(), public.set_marketing_consent(boolean), public.privacy_submit(text, text), public.privacy_resolve(uuid, text, text),
  public.cp_close_hospital(uuid, text, int), public.cp_reopen_hospital(uuid), public.cp_purge_hospital(uuid, text), public.cp_incidents(),
  public.cp_save_incident(jsonb), public.cp_notify_incident(uuid, text), public.cp_retention(), public.cp_save_retention(jsonb), public.cp_health() from public, anon;
grant execute on function public.my_data_export(), public.set_marketing_consent(boolean), public.privacy_submit(text, text), public.privacy_resolve(uuid, text, text),
  public.cp_close_hospital(uuid, text, int), public.cp_reopen_hospital(uuid), public.cp_purge_hospital(uuid, text), public.cp_incidents(),
  public.cp_save_incident(jsonb), public.cp_notify_incident(uuid, text), public.cp_retention(), public.cp_save_retention(jsonb), public.cp_health() to authenticated;


-- =====================================================================================================
--  PHASE 8.2 — SELF-SERVICE FREE-TRIAL SIGN-UP (Hospital Comrade product page → /signup)
-- =====================================================================================================
--  • platform_settings 'signup' { enabled, mode: instant|approve, trialDays, plan, maxPerDay, unclaimedDays, platformUrl }
--    — the platform admin decides in the control panel (Settings → Free-trial sign-up).
--  • platform_trial_signup(p) — anyone (anon): validates, rate-limits, records the accepted Terms version and either
--    creates the hospital right away (instant) or waits for the admin (approve). The person then creates the owner
--    account on the new hospital with the same e-mail (app_settings 'bootstrap', as for panel-created hospitals).
--  • cp_signups / cp_signup_decide — the admin's list with approve / reject.
--  • signup_cleanup() (nightly, from run_retention): pending requests expire after 30 days; hospitals nobody claimed
--    within unclaimedDays are closed (the normal 7-day notice, then the admin may delete them).
--  Platform tables never use a column called tenant_id (the tenancy loops would scope them to a hospital).
-- =====================================================================================================

insert into public.platform_settings (key, data) values ('signup',
  '{"enabled": true, "mode": "approve", "trialDays": 14, "plan": "clinic", "maxPerDay": 25, "unclaimedDays": 14, "platformUrl": ""}'::jsonb)
on conflict (key) do nothing;

create table if not exists public.platform_signups (
  id               uuid primary key default gen_random_uuid(),
  created_at       timestamptz not null default now(),
  organisation     text not null check (char_length(organisation) between 2 and 120),
  contact_name     text not null check (char_length(contact_name) between 2 and 100),
  email            text not null check (char_length(email) <= 150),
  phone            text not null check (char_length(phone) <= 20),
  city             text check (char_length(city) <= 80),
  plan             text not null,
  trial_days       int not null,
  slug             text not null,
  code             text not null,
  status           text not null default 'pending' check (status in ('pending', 'created', 'rejected', 'expired')),
  hospital_id      uuid references public.tenants (id) on delete set null,
  terms_version    text not null check (char_length(terms_version) between 1 and 20),
  ip_hash          text,
  decided_at       timestamptz,
  decided_by       uuid,
  decided_by_name  text,
  reason           text check (char_length(reason) <= 300)
);
create index if not exists platform_signups_status_idx on public.platform_signups (status, created_at desc);
create index if not exists platform_signups_email_idx on public.platform_signups (lower(email));
alter table public.platform_signups enable row level security;
revoke all on public.platform_signups from anon, authenticated;
grant all on public.platform_signups to service_role;

create or replace function public.signup_config()
returns jsonb language sql stable security definer set search_path = public as $$
  select '{"enabled": true, "mode": "approve", "trialDays": 14, "plan": "clinic", "maxPerDay": 25, "unclaimedDays": 14, "platformUrl": ""}'::jsonb
      || coalesce((select data from public.platform_settings where key = 'signup'), '{}'::jsonb)
$$;

-- what the sign-up page needs to know (anyone)
create or replace function public.platform_signup_info()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare c jsonb := public.signup_config(); b jsonb := public.billing_config();
begin
  return jsonb_build_object('enabled', coalesce((c ->> 'enabled')::boolean, false), 'mode', c ->> 'mode',
    'trialDays', (c ->> 'trialDays')::int, 'plan', c ->> 'plan',
    'plans', coalesce((select jsonb_agg(k order by (b -> 'plans' -> k ->> 'monthly')::numeric nulls last) from jsonb_object_keys(b -> 'plans') k), '[]'::jsonb));
end $$;

-- a free short name for the hospital, from its name: "City Care Clinic" → citycareclinic, citycareclinic-2, …
create or replace function public.signup_slug(p_name text)
returns text language plpgsql stable security definer set search_path = public as $$
declare
  base text := left(trim(both '-' from regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '', 'g')), 30);
  s    text;
  i    int := 1;
begin
  if char_length(base) < 3 then base := 'hospital'; end if;
  s := base;
  while s in ('main', 'www', 'app', 'api', 'admin', 'demo', 'mail', 'help', 'status', 'signup', 'legal', 'controlpanel')
     or exists (select 1 from public.tenants where slug = s)
     or exists (select 1 from public.platform_signups where slug = s and status = 'pending') loop
    i := i + 1;
    s := base || '-' || i;
  end loop;
  return s;
end $$;

-- record prefix from the initials: City Care Clinic → CCC, Apollo → APO
create or replace function public.signup_code(p_name text)
returns text language plpgsql immutable as $$
declare clean text := upper(regexp_replace(coalesce(p_name, ''), '[^A-Za-z ]', ' ', 'g')); v text;
begin
  select string_agg(left(w, 1), '') into v from regexp_split_to_table(trim(clean), '\s+') w where w <> '' and w not in ('THE', 'AND', 'OF', 'PVT', 'LTD');
  if char_length(coalesce(v, '')) < 2 then v := left(replace(clean, ' ', ''), 3); end if;
  v := left(coalesce(v, ''), 6);
  return case when char_length(v) >= 2 then v else 'HC' end;
end $$;

-- turns a sign-up request into a hospital (internal) and writes the welcome e-mail
create or replace function public.signup_activate(p_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare s public.platform_signups; r jsonb;
begin
  select * into s from public.platform_signups where id = p_id for update;
  if not found or s.status <> 'pending' then raise exception 'This sign-up was already handled.'; end if;
  if exists (select 1 from public.tenants where slug = s.slug) then
    update public.platform_signups set slug = public.signup_slug(s.organisation) where id = p_id returning * into s;
  end if;
  r := public.hospital_create(jsonb_build_object('slug', s.slug, 'name', s.organisation, 'code', s.code, 'plan', s.plan,
         'owner_email', s.email, 'status', 'trial', 'trial_days', s.trial_days,
         'notes', 'Self-service sign-up · ' || s.contact_name || ' · ' || s.phone || coalesce(' · ' || nullif(s.city, ''), '') || ' · Terms ' || s.terms_version));
  update public.platform_signups set status = 'created', hospital_id = (r ->> 'id')::uuid where id = p_id;
  -- welcome e-mail (Hospital Comrade messaging; best effort — the sign-up page shows the same link)
  perform set_config('app.tenant_id', r ->> 'id', true);
  perform public.notify_enqueue_raw('signup_welcome',
    jsonb_build_object('subject', 'Your free trial of {hospital} is ready',
      'text', 'Namaste {name}, {hospital} is ready — free for {days} days. Create your owner account with this e-mail ({email}) here: {link} . After that, invite your team from Users & Roles. Reply to this e-mail if you need help.'),
    array['email'], s.phone, s.email, null,
    jsonb_build_object('name', split_part(regexp_replace(s.contact_name, '^(dr|mr|mrs|ms|shri|smt)\.?\s+', '', 'i'), ' ', 1),
      'hospital', s.organisation, 'days', s.trial_days, 'email', s.email, 'link', rtrim(coalesce(public.signup_config() ->> 'platformUrl', ''), '/') || '/register?hospital=' || s.slug),
    'tenants', (r ->> 'id')::uuid, null);
  return r;
end $$;

-- the public sign-up form
--   { organisation, name, email, phone, city?, plan?, terms_version, website? (honeypot — must stay empty) }
create or replace function public.platform_trial_signup(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c       jsonb := public.signup_config();
  b       jsonb := public.billing_config();
  v_org   text := trim(regexp_replace(coalesce(p ->> 'organisation', ''), '\s+', ' ', 'g'));
  v_name  text := trim(regexp_replace(coalesce(p ->> 'name', ''), '\s+', ' ', 'g'));
  v_mail  text := lower(trim(coalesce(p ->> 'email', '')));
  v_phone text := right(regexp_replace(coalesce(p ->> 'phone', ''), '\D', '', 'g'), 10);
  v_city  text := nullif(left(trim(coalesce(p ->> 'city', '')), 80), '');
  v_plan  text := coalesce(nullif(p ->> 'plan', ''), c ->> 'plan', 'clinic');
  v_terms text := trim(coalesce(p ->> 'terms_version', ''));
  v_ip    text;
  v_hash  text;
  v_id    uuid;
  v_slug  text;
  r       jsonb;
begin
  if not coalesce((c ->> 'enabled')::boolean, false) then raise exception 'Online sign-up is closed right now — please use the contact form and we will set you up.'; end if;
  if coalesce(p ->> 'website', '') <> '' then raise exception 'Could not sign up.'; end if;
  if char_length(v_org) not between 2 and 120 then raise exception 'Enter your hospital or clinic''s name.'; end if;
  if char_length(v_name) not between 2 and 100 then raise exception 'Enter your name.'; end if;
  if v_mail !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]{2,}$' or char_length(v_mail) > 150 then raise exception 'Enter a valid e-mail — you will sign in with it.'; end if;
  if v_phone !~ '^[6-9][0-9]{9}$' then raise exception 'Enter a 10-digit Indian mobile number.'; end if;
  if v_terms = '' or char_length(v_terms) > 20 then raise exception 'Please accept the Terms of Service and the Data Processing Agreement.'; end if;
  if not (b -> 'plans' ? v_plan) then v_plan := coalesce(c ->> 'plan', 'clinic'); end if;

  -- one account = one hospital
  if exists (select 1 from public.profiles where lower(email) = v_mail and tenant_id is not null and role <> 'patient')
     or exists (select 1 from public.provider_users u join auth.users a on a.id = u.user_id where lower(a.email) = v_mail)
     or exists (select 1 from public.app_settings s where s.key = 'bootstrap' and lower(s.data ->> 'owner_email') = v_mail) then
    raise exception 'This e-mail already belongs to a hospital here — sign in there, or use another e-mail.';
  end if;
  if exists (select 1 from public.platform_signups where lower(email) = v_mail and status = 'pending') then
    raise exception 'We already have a request from this e-mail — we will be in touch soon.';
  end if;

  -- rate limits: per address, per phone, per day for everyone
  begin
    v_ip := nullif(trim(split_part(coalesce(nullif(current_setting('request.headers', true), '')::json ->> 'cf-connecting-ip',
                                         nullif(current_setting('request.headers', true), '')::json ->> 'x-forwarded-for', ''), ',', 1)), '');
  exception when others then v_ip := null; end;
  v_hash := case when v_ip is null then null else md5('hc-signup:' || v_ip) end;
  if v_hash is not null and (select count(*) from public.platform_signups where ip_hash = v_hash and created_at > now() - interval '1 day') >= 3 then
    raise exception 'Too many sign-ups from your network today — please try tomorrow or use the contact form.';
  end if;
  if (select count(*) from public.platform_signups where phone = v_phone and created_at > now() - interval '1 day') >= 2 then
    raise exception 'Too many sign-ups with this mobile number today — please use the contact form.';
  end if;
  if (select count(*) from public.platform_signups where created_at > now() - interval '1 day') >= greatest(coalesce((c ->> 'maxPerDay')::int, 25), 1) then
    raise exception 'We are getting a lot of sign-ups today — please leave your details in the contact form and we will set you up.';
  end if;

  v_slug := public.signup_slug(v_org);
  insert into public.platform_signups (organisation, contact_name, email, phone, city, plan, trial_days, slug, code, terms_version, ip_hash)
  values (v_org, v_name, v_mail, v_phone, v_city, v_plan, greatest(1, least(90, coalesce((c ->> 'trialDays')::int, 14))), v_slug, public.signup_code(v_org), v_terms, v_hash)
  returning id into v_id;

  if c ->> 'mode' = 'instant' then
    r := public.signup_activate(v_id);
    return jsonb_build_object('status', 'created', 'slug', r ->> 'slug', 'email', v_mail, 'trial_days', greatest(1, least(90, coalesce((c ->> 'trialDays')::int, 14))));
  end if;
  return jsonb_build_object('status', 'pending', 'email', v_mail);
end $$;

-- ------------------------------------------------------------------ control panel
create or replace function public.cp_signups(p_status text default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return coalesce((select jsonb_agg(to_jsonb(s) - 'ip_hash' || jsonb_build_object(
      'hospital_slug', t.slug,
      'owner_joined', exists (select 1 from public.profiles p where p.tenant_id = s.hospital_id and p.role = 'owner'))
      order by (s.status = 'pending') desc, s.created_at desc)
    from (select * from public.platform_signups where p_status is null or status = p_status order by created_at desc limit 300) s
    left join public.tenants t on t.id = s.hospital_id), '[]'::jsonb);
end $$;

-- approve (creates the hospital) or reject a pending request
create or replace function public.cp_signup_decide(p_id uuid, p_action text, p_reason text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare s public.platform_signups; r jsonb;
begin
  perform public.cp_require(array['admin']);
  select * into s from public.platform_signups where id = p_id for update;
  if not found then raise exception 'Sign-up not found'; end if;
  if s.status <> 'pending' then raise exception 'This sign-up was already handled.'; end if;
  if p_action = 'approve' then
    r := public.signup_activate(p_id);
    perform set_config('app.tenant_id', '', true);
  elsif p_action = 'reject' then
    update public.platform_signups set status = 'rejected', reason = nullif(left(trim(coalesce(p_reason, '')), 300), '') where id = p_id;
  else
    raise exception 'Unknown action %', p_action;
  end if;
  update public.platform_signups set decided_at = now(), decided_by = auth.uid(), decided_by_name = (select full_name from public.profiles where id = auth.uid()) where id = p_id;
  perform public.provider_log('signup:' || p_action, s.organisation, jsonb_build_object('email', s.email, 'slug', r ->> 'slug', 'reason', p_reason));
  return (select to_jsonb(x) - 'ip_hash' from public.platform_signups x where x.id = p_id);
end $$;

create or replace function public.cp_signup_settings()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.cp_require(array['admin']);
  return public.signup_config() || jsonb_build_object('pending', (select count(*) from public.platform_signups where status = 'pending'));
end $$;

create or replace function public.cp_save_signup_settings(p jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare k text; v jsonb := coalesce(p, '{}'::jsonb);
begin
  perform public.cp_require(array['admin']);
  for k in select jsonb_object_keys(v) loop
    if k not in ('enabled', 'mode', 'trialDays', 'plan', 'maxPerDay', 'unclaimedDays', 'platformUrl') then raise exception 'Unknown setting %', k; end if;
  end loop;
  if v ? 'enabled' and jsonb_typeof(v -> 'enabled') <> 'boolean' then raise exception 'enabled: true or false'; end if;
  if v ? 'mode' and v ->> 'mode' not in ('instant', 'approve') then raise exception 'Mode: instant or approve.'; end if;
  if v ? 'trialDays' and coalesce((v ->> 'trialDays')::int, 0) not between 1 and 90 then raise exception 'Trial: 1 to 90 days.'; end if;
  if v ? 'plan' and not (public.billing_config() -> 'plans' ? (v ->> 'plan')) then raise exception 'Unknown plan %', v ->> 'plan'; end if;
  if v ? 'maxPerDay' and coalesce((v ->> 'maxPerDay')::int, 0) not between 1 and 1000 then raise exception 'Sign-ups per day: 1 to 1000.'; end if;
  if v ? 'platformUrl' and coalesce(v ->> 'platformUrl', '') !~ '^(https://[a-z0-9.-]+(:[0-9]+)?/?)?$' then raise exception 'Website: https://your-domain (or leave empty).'; end if;
  if v ? 'unclaimedDays' and coalesce((v ->> 'unclaimedDays')::int, 0) not between 3 and 90 then raise exception 'Unclaimed trials: close after 3 to 90 days.'; end if;
  update public.platform_settings set data = data || v, updated_at = now() where key = 'signup';
  perform public.provider_log('settings:signup', null, v);
  return public.cp_signup_settings();
end $$;

-- nightly (run_retention): expire old requests, close hospitals nobody claimed
create or replace function public.signup_cleanup()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare c jsonb := public.signup_config(); n_exp bigint; n_close bigint := 0; r record;
begin
  update public.platform_signups set status = 'expired', reason = 'No decision within 30 days' where status = 'pending' and created_at < now() - interval '30 days';
  get diagnostics n_exp = row_count;
  for r in select s.id, s.hospital_id from public.platform_signups s join public.tenants t on t.id = s.hospital_id
            where s.status = 'created' and t.closing_at is null and not t.is_primary and t.paid_until is null
              and s.created_at < now() - make_interval(days => greatest(coalesce((c ->> 'unclaimedDays')::int, 14), 3))
              and not exists (select 1 from public.profiles p where p.tenant_id = s.hospital_id and p.role = 'owner') loop
    update public.tenants set closing_at = now(), purge_after = now() + interval '7 days', close_reason = 'Unclaimed free trial (self-service sign-up)', updated_at = now() where id = r.hospital_id;
    update public.platform_signups set status = 'expired', reason = 'Owner never signed up' where id = r.id;
    n_close := n_close + 1;
  end loop;
  delete from public.platform_signups where status in ('rejected', 'expired') and hospital_id is null
     and created_at < now() - make_interval(days => greatest(coalesce((public.retention_config() ->> 'leadDays')::int, 1095), 30));
  return jsonb_build_object('expired', n_exp, 'closed', n_close);
end $$;

revoke all on function public.signup_config(), public.signup_slug(text), public.signup_activate(uuid), public.signup_cleanup() from public, anon, authenticated;
revoke all on function public.platform_signup_info(), public.platform_trial_signup(jsonb) from public;
grant execute on function public.platform_signup_info(), public.platform_trial_signup(jsonb) to anon, authenticated;
revoke all on function public.cp_signups(text), public.cp_signup_decide(uuid, text, text), public.cp_signup_settings(), public.cp_save_signup_settings(jsonb) from public, anon;
grant execute on function public.cp_signups(text), public.cp_signup_decide(uuid, text, text), public.cp_signup_settings(), public.cp_save_signup_settings(jsonb) to authenticated;
grant execute on function public.signup_cleanup() to service_role;


-- =====================================================================================================
--  PHASE 8.3 — LAUNCH CHECK (control panel → System health → Launch checklist)
-- =====================================================================================================
--  cp_launch_check() looks at what the database can see and answers ok / warn / fail per item:
--  demo logins left over, platform admins, seller details on invoices, scheduled jobs, row-level security on every
--  table, the nightly clean-up, sign-up settings, failing messages. Things outside the database (Razorpay live keys,
--  SMTP, backups, DNS) are listed by the panel as manual checks — see docs/GO_LIVE.md.
-- =====================================================================================================

create or replace function public.cp_launch_check()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  out     jsonb := '[]'::jsonb;
  b       jsonb := public.billing_config();
  s       jsonb := public.signup_config();
  v_cron  boolean := exists (select 1 from pg_extension where extname = 'pg_cron');
  v_jobs  text[] := '{}';
  v_miss  text[];
  v_list  text;
  v_n     bigint;
  v_m     bigint;
  v_at    timestamptz;
begin
  perform public.cp_require(array['admin']);

  -- 1. sample logins (master.sql) must not exist on a live platform
  select string_agg(email, ', ' order by email), count(*) into v_list, v_n from auth.users
   where lower(email) like '%@dchospital.com' or lower(email) like '%@citycare.demo' or lower(email) like '%@hospitalcomrade.demo';
  out := out || jsonb_build_object('id', 'demo_logins', 'title', 'No demo logins', 'status', case when v_n = 0 then 'ok' else 'fail' end,
    'detail', case when v_n = 0 then 'No sample accounts (Demo@123) exist.' else v_n || ' sample account(s) with the public password Demo@123: ' || left(v_list, 300) || ' — install with production.sql or delete them.' end);

  -- 2. the City Care sample hospital
  select count(*) into v_n from public.tenants where id = 'b0000000-0000-4000-8000-000000000002';
  out := out || jsonb_build_object('id', 'demo_hospital', 'title', 'No sample hospital', 'status', case when v_n = 0 then 'ok' else 'warn' end,
    'detail', case when v_n = 0 then 'The City Care sample clinic is not installed.' else 'The City Care sample clinic is installed — close and delete it before you invite customers.' end);

  -- 3. platform admins (two, so nobody gets locked out)
  select count(*) into v_n from public.provider_users where active and role = 'admin';
  out := out || jsonb_build_object('id', 'admins', 'title', 'Platform admins', 'status', case when v_n >= 2 then 'ok' when v_n = 1 then 'warn' else 'fail' end,
    'detail', case when v_n >= 2 then v_n || ' active admins.' when v_n = 1 then 'Only one admin — add a second one (Team) so the platform is never locked out.' else 'No active admin.' end);

  -- 4. seller details printed on every invoice
  v_miss := array_remove(array[
    case when coalesce(b -> 'seller' ->> 'name', '') = '' then 'legal name' end,
    case when coalesce(b -> 'seller' ->> 'gstin', '') = '' then 'GSTIN' end,
    case when coalesce(b -> 'seller' ->> 'address', '') = '' then 'address' end,
    case when coalesce(b -> 'seller' ->> 'email', '') = '' then 'e-mail' end], null);
  out := out || jsonb_build_object('id', 'seller', 'title', 'Invoice details (seller)', 'status', case when cardinality(v_miss) = 0 then 'ok' else 'fail' end,
    'detail', case when cardinality(v_miss) = 0 then 'Printed on invoices as ' || (b -> 'seller' ->> 'name') || ', GSTIN ' || (b -> 'seller' ->> 'gstin') || '.'
                   else 'Missing: ' || array_to_string(v_miss, ', ') || ' — Platform settings → Seller.' end);

  -- 5. scheduled jobs (reminders, message delivery, nightly clean-up)
  if v_cron then
    execute $q$ select coalesce(array_agg(jobname::text), '{}') from cron.job where active and jobname like 'dch-%' $q$ into v_jobs;
  end if;
  v_miss := array(select j from unnest(array['dch-notify-flush', 'dch-appointment-reminders', 'dch-billing-reminders', 'dch-retention']) j where not (j = any (v_jobs)));
  out := out || jsonb_build_object('id', 'jobs', 'title', 'Scheduled jobs', 'status', case when not v_cron then 'fail' when cardinality(v_miss) = 0 then 'ok' else 'fail' end,
    'detail', case when not v_cron then 'pg_cron is not enabled (Supabase → Database → Extensions).'
                   when cardinality(v_miss) = 0 then 'Message delivery, reminders and the nightly clean-up are scheduled.'
                   else 'Not scheduled: ' || array_to_string(v_miss, ', ') || ' — switch automatic delivery off and on once in the main hospital''s Settings → Notifications.' end);

  -- 6. pg_net (the database calls the notify / billing functions)
  out := out || jsonb_build_object('id', 'pg_net', 'title', 'Outgoing calls (pg_net)', 'status', case when exists (select 1 from pg_extension where extname = 'pg_net') then 'ok' else 'fail' end,
    'detail', case when exists (select 1 from pg_extension where extname = 'pg_net') then 'Enabled.' else 'Enable pg_net (Supabase → Database → Extensions) — messages are not delivered without it.' end);

  -- 7. row-level security on every table
  select string_agg(c.relname, ', ' order by c.relname), count(*) into v_list, v_n from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity;
  out := out || jsonb_build_object('id', 'rls', 'title', 'Row-level security', 'status', case when v_n = 0 then 'ok' else 'fail' end,
    'detail', case when v_n = 0 then 'Every table is protected.' else 'Without RLS: ' || left(v_list, 300) end);

  -- 8. every per-hospital table keeps hospitals apart
  select string_agg(c.table_name, ', ' order by c.table_name), count(*) into v_list, v_n from information_schema.columns c
    join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name and t.table_type = 'BASE TABLE'
   where c.table_schema = 'public' and c.column_name = 'tenant_id' and c.table_name not in ('tenants', 'tenant_domains', 'provider_audit', 'provider_assignments')
     and not exists (select 1 from pg_policies p where p.schemaname = 'public' and p.tablename = c.table_name and p.policyname = 'tenant_isolation');
  out := out || jsonb_build_object('id', 'isolation', 'title', 'Hospital isolation', 'status', case when v_n = 0 then 'ok' else 'fail' end,
    'detail', case when v_n = 0 then 'Every per-hospital table has the tenant_isolation policy.' else 'Missing tenant_isolation: ' || left(v_list, 300) || ' — run supabase/upgrade-2026-10.sql again.' end);

  -- 9. nightly clean-up actually ran
  v_at := (public.retention_config() -> 'last_run' ->> 'at')::timestamptz;
  out := out || jsonb_build_object('id', 'retention', 'title', 'Nightly clean-up', 'status', case when v_at > now() - interval '2 days' then 'ok' else 'warn' end,
    'detail', case when v_at is null then 'Has never run yet — it runs at 03:00 IST once jobs are scheduled.' when v_at > now() - interval '2 days' then 'Last ran ' || to_char(v_at at time zone 'Asia/Kolkata', 'DD Mon HH24:MI') || ' IST.'
                   else 'Last ran ' || to_char(v_at at time zone 'Asia/Kolkata', 'DD Mon YYYY') || ' — check System health → Scheduled jobs.' end);

  -- 10. free-trial sign-up
  out := out || jsonb_build_object('id', 'signup', 'title', 'Free-trial sign-up', 'status',
      case when not coalesce((s ->> 'enabled')::boolean, false) then 'ok' when coalesce(s ->> 'platformUrl', '') = '' then 'warn' else 'ok' end,
    'detail', case when not coalesce((s ->> 'enabled')::boolean, false) then 'Closed — people use the contact form.'
                   when coalesce(s ->> 'platformUrl', '') = '' then 'Open, but the product website address is empty — the welcome e-mail''s link will be relative. Set it in Sign-ups.'
                   else 'Open (' || case when s ->> 'mode' = 'instant' then 'created instantly' else 'reviewed first' end || ', ' || (s ->> 'trialDays') || ' days).' end);

  -- 11. messages failing in the last 24 hours
  select count(*) filter (where status = 'failed'), count(*) into v_n, v_m from public.notification_outbox where created_at > now() - interval '24 hours';
  out := out || jsonb_build_object('id', 'messages', 'title', 'Messages delivered', 'status', case when v_m = 0 or v_n * 5 <= v_m then 'ok' else 'warn' end,
    'detail', case when v_m = 0 then 'No messages in the last 24 hours.' else v_n || ' of ' || v_m || ' failed in the last 24 hours' || case when v_n * 5 > v_m then ' — see System health → Recent failures.' else '.' end end);

  -- 12. the platform's own hospital has its owner
  select count(*) into v_n from public.profiles p join public.tenants t on t.id = p.tenant_id where t.is_primary and p.role = 'owner';
  out := out || jsonb_build_object('id', 'primary_owner', 'title', 'Main hospital owner', 'status', case when v_n > 0 then 'ok' else 'warn' end,
    'detail', case when v_n > 0 then 'The main hospital has an owner account.' else 'Nobody has signed up as the main hospital''s owner yet (the bootstrap e-mail in production.sql).' end);

  return jsonb_build_object('at', now(), 'checks', out);
end $$;

revoke all on function public.cp_launch_check() from public, anon;
grant execute on function public.cp_launch_check() to authenticated;


-- =====================================================================================================
--  14. GO-LIVE DEFAULTS
-- =====================================================================================================
-- ✏️  The first account created with this e-mail becomes the hospital Owner:
insert into public.app_settings (key, data) values ('bootstrap', jsonb_build_object('owner_email', 'owner@your-hospital.in'))
on conflict (tenant_id, key) do update set data = excluded.data;

-- an existing account with that e-mail (created before running this file) is promoted right away
update public.profiles set role = 'owner'
where lower(email) = lower((select data ->> 'owner_email' from public.app_settings where key = 'bootstrap'))
  and not exists (select 1 from public.profiles where role = 'owner');

-- demo helpers off
insert into public.site_content (key, data)
values ('settings', '{"portal": {"showDemoLogins": false}, "booking": {"showDemoOtp": false}}'::jsonb)
on conflict (tenant_id, key) do update set data = public.site_content.data
  || jsonb_build_object('portal', coalesce(public.site_content.data -> 'portal', '{}'::jsonb) || '{"showDemoLogins": false}'::jsonb,
                        'booking', coalesce(public.site_content.data -> 'booking', '{}'::jsonb) || '{"showDemoOtp": false}'::jsonb);
commit;

